  families = {
    ["air-elementals"] = { title = "Luftelementare", note = { { "Staubteufel ziehen über offene Felder, während größere Wirbelwinde in Desolace und Silithus Gestalt annehmen. Ein Luftelementar ist am leichtesten an dem zu erkennen, was er um sich sammelt: Staub, Wolken und die losen Dinge, die ein Reisender sicher verpackt glaubte." }, { "Der Twilight-Hammer beschwört in der südlichen Wüste elementare Mächte. Ein Sturm, dem man dort begegnet, kann mehr hinter sich haben als unruhiges Wetter. Der Wind hat eine Gestalt angenommen, und vielleicht hat ihn jemand eingeladen." } } },
    ["bandits-and-mercenaries"] = { title = "Banditen und Söldner", note = { { "Ein Steckbrief lässt einen Gesetzlosen wie ein einzelnes Problem aussehen. Die Lager der Wüstenläufer in Tanaris und Kurzens Truppenlager im Schlingendorntal sprechen dagegen: Wachen, Vorräte und eine Organisation, die den Verlust jedes einzelnen Banditen übersteht." }, { "Kurzens Gefolgsleute waren Soldaten, bevor der Dschungel ihre Expedition in seinen Griff nahm. Andere arbeiten für Sold oder lauern auf den Straßen. Ihre Gründe sind verschieden, und die Banner mögen fehlen, doch ein bewachtes Lager hat viel mit dem Heer gemein, zu dem es einst gehörte." } } },
    ["basilisks"] = { title = "Basilisken", note = { { "Ein Basilisk kann für ein Stück zerbrochenen Fels gelten, bis er sich bewegt. Sein flacher Körper und seine dicke Haut passen zu den trockenen Hügeln des Schlingendorntals und den Wüsten des Südens. Die Kristalle auf manchen älteren Exemplaren machen die Ähnlichkeit recht überzeugend." }, { "Schwierig ist der Blick. Diese Echsen können einen lebenden Gegner starr wie Stein zurücklassen, und so wird das übliche Geschäft des Naturkundlers, genauer hinzusehen, zu einer heiklen Verhandlung. An einem Basilisken gibt es viel zu bewundern, vorausgesetzt, er schaut gerade woandershin." } } },
    ["bats"] = { title = "Fledermäuse", note = { { "Eine Höhle, die bei Tageslicht leer wirkt, kann eine Decke voller Fledermäuse haben. Nachtsauger hängen über den Pfaden von Tirisfal, während die dornigen Gänge von Razorfen ihre eigenen Kolonien beherbergen. Flügel füllen einen überraschend großen Teil eines engen Tunnels." }, { "Die Seuchenfledermäuse der östlichen Lande gehören in einen weniger heiteren Bericht. Krankheit reist mit ihnen durch ein Land, das die Geißel bereits verwüstet hat. Die Gestalt einer Fledermaus ist vertraut. Was sie mit sich trägt, hängt sehr davon ab, wo sie geschlafen hat." } } },
    ["bears"] = { title = "Bären", note = { { "Von den Schwarzbären Khaz Modans bis zu den weißen Splitterzahnbären von Winterspring lassen Bären einen Wald gut bewohnt wirken, selbst wenn sonst wenig zu sehen ist. Ein breiter Rücken zwischen den Bäumen, eine schwere Pranke auf dem Pfad, und das Unterholz fühlt sich plötzlich weniger leer an." }, { "Ihre Stärke hat ihnen einen Platz in den Künsten der Druiden ebenso wie in den Geschichten der Jäger eingebracht. Für einen Bären aber geht es zunächst um eigene Angelegenheiten: Nahrung, Revier und was auch immer ihm gerade zu nahe gekommen ist. Man kann einen durchaus bewundern, ohne Teil dieser Angelegenheiten zu werden." } } },
    ["birds"] = { title = "Vögel der Höhen", note = { { "Wer von einem Gebirgspass aufblickt, sieht vielleicht die Flügel eines Hippogryphen, eines Windreiters oder eines Greifen. Reisende ordnen alle drei ungefähr derselben Kategorie zu. Das Geweih, die stechenden Schwänze und die gebogenen Schnäbel legen nahe, dass ein Naturkundler sich etwas mehr Mühe geben sollte." }, { "Hippogryphen tragen Nachtelfen als Reiter, Greifen sind den Wildhammer vertraute Gefährten, und die Horde hat ihre Windreiter. Jenseits der Horste und Nester füllen ihre wilden Verwandten denselben Himmel. Ein Sattel ist eine beachtliche Leistung bei jedem Geschöpf, das einfach davonfliegen kann." } } },
    ["black-dragonflight"] = { title = "Der schwarze Drachenschwarm", note = { { "Schwarze Drachkin bewohnen ein Land, das von Feuer und zerbrochenem Stein gezeichnet ist. Welpen tauchen im Rotkammgebirge und im Ödland auf. Größere Diener bewachen Nefarians Festung in der Blackrockspitze und Onyxias Hort in Dustwallow." }, { "Todesschwinges Verrat lastet auf dem Schwarm, während seine Kinder eigene Ziele verfolgen. Nefarians Experimente spannen Drachen verschiedener Farben in dasselbe schreckliche Werk ein. Ein Naturkundler, der gewohnt ist, die Unterschiede zwischen den Schwärmen zu beschreiben, findet sehr wenig Trost in dem, was Nefarian aus ihnen zu machen versucht." } } },
    ["blackrock"] = { title = "Der Blackrockklan", note = { { "Die Orcs der Blackrock halten die Straßen um ihren Berg ebenso wie die Hallen in seinem Inneren. Von der Brennenden Steppe aus reichen ihre Plünderer bis ins Rotkammgebirge, wo Burg Steinwacht den Leuten von Seenhain die Stärke des Klans beständig vor Augen hält." }, { "Rend Blackhand beansprucht den Titel des Kriegshäuptlings, obwohl seine Gefolgsleute unter Nefarians Schwingen dienen. Sie tragen die Waffen und den Ehrgeiz der alten Horde in eine Welt, in der Thrall eine andere aufzubauen versucht. Der Unterschied ist sichtbar, lange bevor ein Reisender die Spitze erreicht." } } },
    ["blighted-elementals"] = { title = "Verderbte Elementare", note = { { "Die Teergruben von Un'Goro und der vergiftete Boden des Teufelswalds bringen beide sich bewegende Gestalten hervor, doch man sollte ihnen nicht dieselbe Geschichte zuschreiben, bloß weil keine von beiden angenehm anzufassen ist. Teerbestien gehören zum Krater. Toxinschrecken gehören zu einem verwundeten Wald." }, { "Die Verstrahlung Gnomeregans und die Seuche der Pestländer fügen dieser unruhigen Seite weitere Beispiele hinzu. Jedes trägt etwas von dem Ort in sich, der es geformt hat. Ihre Unterschiede zählen: Was aus dem Boden aufsteigt, kann einem Naturkundler sagen, was mit dem Boden selbst geschehen ist." } } },
    ["blue-dragonflight"] = { title = "Der blaue Drachenschwarm", note = { { "Blaue Drachkin bewachen arkane Orte: die alten Ruinen von Azshara und die eisigen Hallen von Mazthoril. Malygos' Schwarm trägt seit langem die Verantwortung für die Magie, was einen Sterblichen, der zwischen solchen Schätzen herumstöbert, von Anfang an in eine heikle Lage bringt." }, { "Azuregos wacht über Azshara mit einer ausgesprochen persönlichen Haltung gegenüber Besuchern. Sein Handel um ein altes magisches Kontobuch verrät Sinn für Humor. Uralte Pflicht hat ihn nicht daran gehindert, die Botengänge eines Abenteurers amüsant zu finden." } } },
    ["boars"] = { title = "Eber", note = { { "Eber tauchen in den roten Schluchten von Durotar ebenso bereitwillig auf wie auf den grünen Feldern von Elwynn. Die Färbung wechselt, und ein Klippeneber hat ein feines Fell gegen den Schnee, doch die Hauer geben denselben unverkennbaren Umriss." }, { "Die Geiferzähne von Westfall sind eine Plage für die Höfe und ein nützlicher Fleischvorrat. Das bringt den Eber in die unglückliche Lage, aus einem Feld heraus und in einen Kochtopf hinein gewünscht zu werden, oft von derselben Person. Er wehrt sich gewöhnlich gegen beides." } } },
    ["bronze-dragonflight"] = { title = "Der bronzene Drachenschwarm", note = { { "Die Höhlen der Zeit öffnen sich unter Tanaris, doch die Angelegenheiten des bronzenen Schwarms reichen weit über dieses Stück Wüste hinaus. Nozdormus Drachen bewachen die Zeit selbst, ein Unterfangen, für das die Liga keine befriedigenden Messinstrumente besitzt." }, { "Ihr Anteil an der Versiegelung von Ahn'Qiraj gehört zur verbürgten Geschichte. Anachronos wacht noch immer vor den Höhlen über die Wüste, ein gewaltiger lebender Zeuge eines Krieges, dessen übrige Spuren unter dem Sand liegen." } } },
    ["burning-blade"] = { title = "Die Burning Blade", note = { { "Der Name der Burning Blade lebt auf den Lippen von Hexenmeistern und Dämonenanbetern fort. Ihre Kultisten besetzen Höhlen in Durotar und versammeln sich in Desolace. Unter Orgrimmar rückt der Ragefireabgrund diese Gefolgschaft unangenehm nah an die neue Heimat der Horde." }, { "Thralls Volk hat gekämpft, um der Herrschaft der Legion zu entkommen. Diese Kultisten laden ihre Diener zurück, mit Beschwörungskreisen in genau dem Land, in dem sich die befreiten Orcs niedergelassen haben. Für ein Volk, das eine ältere Lebensweise zurückgewinnt, sind sie ein besonders bitterer Nachbar." } } },
    ["burning-legion"] = { title = "Die Brennende Legion", note = { { "Die Gegenwart der Legion verändert eine Landschaft. Im Teufelswald tragen die Bäume den Schaden. In den Verwüsteten Landen halten Dämonen den Boden um das Dunkle Portal besetzt. Mannorocs Koven und der Demonfall-Canyon haben ihre eigenen überlebenden Mahnmale der Invasion." }, { "Ihre Ränge unterscheiden sich gewaltig: Ein Teufelshund jagt Magie, eine Höllenbestie bringt Stein und Flamme, und ein Wichtel kann auf sehr wenig Raum bemerkenswert viel Ärger anrichten. Die Kriege, die sie hierherbrachten, sind vorbei, doch eine Karte ihrer verbliebenen Lager ist alles andere als leer." } } },
    ["carrion-birds"] = { title = "Aasvögel", note = { { "Die Aasvögel sind die Geduldigen: Geier, Bussarde und Kondore, die über dem Brachland, dem Ödland und Tausend Nadeln kreisen und darauf warten, dass das Land das Töten für sie erledigt. Die Fleischreißer von Westfall sind kühner geworden, seit die Höfe leer stehen, und warten nicht immer." }, { "Sie sind ein Zeichen, das zu lesen sich lohnt. Ein Kreis von ihnen am Himmel bedeutet, dass darunter etwas gestorben ist oder gleich sterben wird, und manchmal ist es klug, herauszufinden, was es ist, bevor man hineinläuft." }, { "Die Rocs des fernen Südens sind etwas anderes: große Raubvögel, die lebendes Wild jagen und einen Reisenden als solches betrachten." } } },
    ["centaurs"] = { title = "Zentauren", note = { { "Zentaurenklans bevölkern das offene Land Kalimdors, ihre Dörfer und Kriegstrupps über das Brachland, Desolace und Tausend Nadeln verteilt. Die Tauren kennen sie seit Generationen als Verfolger. In Desolace stehen die Namen Gelkis, Magram und Maraudine für rivalisierende Ansprüche ebenso wie für verschiedene Lager." }, { "Mit manchen dieser Klans kann ein Reisender verhandeln, doch die Freundschaft des einen kostet leicht die eines anderen. Ihre Schamanen sprechen von der Erde, und Theradras hat ihre Anbeter unter ihnen. Hier gibt es mehr als einen Überfall, von der Straße aus gesehen." }, { "Ihre Abstammung führt zurück zu Theradras und Zaetar, dem Sohn des Cenarius, den seine eigenen Kinder töteten. Maraudon birgt diese Familiengeschichte in einer besonders unglücklichen Gestalt." } } },
    ["chimaeras"] = { title = "Chimären", note = { { "Zwei Köpfe auf einem geflügelten Leib machen eine Chimäre unverwechselbar, noch bevor ihr Atem trifft. Die Nachtelfen haben an der Seite dieser Geschöpfe gekämpft, deren Kraft und ätzender Angriff gegen Stein ebenso furchterregend sind wie gegen Fleisch." }, { "Winterspring hat eine blasse, zottige Art, die zum Schnee passt. Vor Feralas beherbergt die Insel des Schreckens die gewaltigen Chimaeroks. Auf einer Karte ist sie eine kleine Insel. Ein Chimaerok gibt einem Reisenden reichlich Anlass zu überlegen, wie viel davon zwischen dem Tier und dem Ufer liegt." } } },
    ["crabs"] = { title = "Krabben", note = { { "Eine Krabbe trägt eine kleine Festung am Strand entlang. Der Panzer bestreitet den größten Teil der Auseinandersetzung, die Scheren regeln den Rest, und das Ganze bewegt sich mit bewundernswerter Selbstsicherheit seitwärts." }, { "Sandkriecher und Brandungskriecher bevölkern Strände auf beiden Kontinenten. Köche schätzen ihr Fleisch, während ein ungestörter Sandstreifen einem Naturkundler etwas Sehenswertes bietet: ein Geschöpf, das an der Grenze zwischen Land und Meer seinen Geschäften nachgeht. Nicht alles an einem Strand wartet auf ein Schiff." } } },
    ["crocolisks"] = { title = "Krokilisken", note = { { "Krokilisken sind uralte Wesen, langkieferig und gepanzert, die Reiche überdauert haben, indem sie einfach still in warmem Wasser lagen und fraßen, was zum Trinken kam. Sie bewohnen die Seen Khaz Modans, die Moore des Sumpflands, die Flüsse des Schlingendorntals und die Ufer von Dustwallow." }, { "Ein Krokilisk am Ufer sieht aus, als schliefe er. Er schläft nicht. Er kann die Strecke zu einem unachtsamen Reisenden schneller zurücklegen, als es sich für etwas so Schweres gehört." }, { "Ihre Häute geben feines Leder, und ihr Fleisch ist besser, als es eigentlich sein dürfte. Beides ist kein Bein wert." } } },
    ["cult-of-the-damned"] = { title = "Der Kult der Verdammten", note = { { "Unter den Toten der Geißel stehen Menschen, die noch am Leben sind. Der Kult der Verdammten liefert Nekromanten, Akolythen und willige Hände für ein Heer, das sonst alle seine Rekruten selbst herstellen müsste." }, { "Die Scholomance unter Caer Darrow gibt diesen Künsten eine Schule, mit Unterricht zwischen den Überresten von Lordaeron. Anderswo hütet der Kult Seuchenkessel und erweckt die Gefallenen. Ein lebender Gelehrter an einem Schreibpult sollte ein beruhigender Anblick sein. Hier macht der Gegenstand des Studiums den ganzen Unterschied." } } },
    ["dark-iron-dwarves"] = { title = "Dunkeleisenzwerge", note = { { "Die Arbeit der Dunkeleisenzwerge ist unverkennbar zwergisch: tiefe Minen, schwere Befestigungen und Maschinen, die gebaut sind, um ihre Erbauer zu überdauern. Die Feste des Klans unter dem Blackrock ist eine Stadt ebenso wie eine Festung, mit Schmieden, einer Arena und dem Hof eines Imperators." }, { "Der Krieg der drei Hämmer machte sie zu Feinden Ironforges. Thaurissans Beschwörung machte sie zu Untertanen von Ragnaros. Ihre Agenten wirken heute weit jenseits des Berges, in Steinbrüchen und Lagern überall in Khaz Modan." }, { "Schwarzpulver und feines Mauerwerk findet man auch in den Händen anderer Zwerge. Es ist die Richtung der Kanone, die diese Seite schwierig macht." } } },
    ["defias"] = { title = "Die Bruderschaft der Defias", note = { { "Eine rote Maske kann einen Taschendieb auf einer Straße in Elwynn bedeuten oder einen Handwerker bei der Arbeit unter den Todesminen. Die Bruderschaft der Defias erwuchs aus der unbezahlten Arbeit der Steinmetze beim Wiederaufbau von Stormwind, und Edwin van Cleef trug diesen Groll nach Westfall." }, { "Die Höfe leiden nun unter einem Streit, den ihre Besitzer nicht beigelegt haben. Unter Moonbrook hat die Bruderschaft etwas weit Größeres als Straßenraub aufgebaut: Werkstätten, angeheuerte Schläger und ein Schiff. Das Können der Steinmetze hat überlebt. Die Stadt, der es dienen sollte, ist zu ihrem Ziel geworden." } } },
    ["dragonmaw"] = { title = "Der Dragonmawklan", note = { { "Die Dragonmaw zogen einst mit roten Drachen in den Krieg, indem sie Alexstrasza in Grim Batol gefangen hielten. Die Befreiung der Königin brach diese Macht, doch der Klan hat noch immer Lager im Sumpfland, wo seine Standarten eine vertraute Gefahr entlang der Straßen sind." }, { "Ihre Überfälle gehören zu den Restkriegen der alten Horde. Grim Batol selbst wird nun vom roten Schwarm bewacht, eine eindrucksvolle Erinnerung daran, dass der Klan einst eine weit größere Gefangene hielt, als seine verbliebenen Krieger je nehmen könnten." } } },
    ["druids-of-the-fang"] = { title = "Die Druiden des Giftzahns", note = { { "Naralex betrat die Höhlen des Wehklagens in der Hoffnung, das Brachland durch den Smaragdgrünen Traum zu erneuern. Er schläft noch immer dort, und der Albtraum, der ihn ergriff, hat sowohl die Tiere der Höhle als auch seine Schüler verändert." }, { "Die Druiden des Giftzahns tragen Schlangennamen und nehmen Schlangengestalt an: Kobrahn, Anacondra, Pythas und Serpentis. Ihre Riten erfüllen Höhlen, die der Anfang eines grüneren Landes sein sollten. Wasser und Wachstum gibt es unter dem Brachland reichlich. Das Problem ist, was mit ihnen gewachsen ist." } } },
    ["earth-elementals"] = { title = "Erdelementare", note = { { "Erdelementare bringen den Hang mit sich: schwere Gestalten aus Fels, die durch das Ödland ziehen, Leiber aus Obsidian in den versengten Landen um den Blackrock. Der Unterschied zwischen einem Felsblock und einem Bewohner kann sich rasch erledigen." }, { "Uldaman beherbergt außerdem Steinbewahrer, Konstrukte, die einen erbauten Ort bewachen, statt wilde Geister, die durch offenes Land streifen. Für die Liga ist dieser Unterschied beträchtlich. Ein Felselementar mag ein Merkmal der Landschaft sein. Ein steinerner Wächter beweist, dass jemand etwas zu beschützen hatte." } } },
    ["earthen"] = { title = "Die Irdenen", note = { { "Die Irdenen sind Wesen aus lebendem Stein, von den Titanen geschaffen, um die tiefen Orte der Welt zu formen, und in Uldaman wandeln einige von ihnen noch immer durch die Hallen des Titanengewölbes und bewachen es, wie sie es sollen." }, { "Die Platinscheiben in diesem Gewölbe sagen, dass die Zwerge von ihnen abstammen. Sie sind, im schlichtesten Sinne, meine Vorfahren, und sie werden versuchen, dich zu töten." }, { "Ich verzeichne sie mit einem Respekt, den ich nicht recht erklären kann, und einer Vorsicht, die ich sehr wohl erklären kann." } } },
    ["faerie-dragons"] = { title = "Feendrachen", note = { { "Ein Feendrache bringt leuchtende Flügel und einen kleinen, flinken Körper in die alten Wälder Kalimdors. Trotz seines Namens und seines Platzes auf dieser Seite ist er kein kleines Mitglied eines der großen Drachenschwärme." }, { "Diese Geschöpfe sind mit dem Smaragdgrünen Traum verbunden und haben ein eigentümliches Verhältnis zur Magie. Die Nachtelfen kennen sie als Verbündete des Waldes. Die Deviatfeendrachen in den Höhlen des Wehklagens gehören in eine weit weniger glückliche Umgebung. Die Farbe allein gibt nur dürftig Auskunft darüber, was einem Geschöpf dort widerfahren ist." } } },
    ["fire-elementals"] = { title = "Feuerelementare", note = { { "Lebende Flammen wandeln durch das versengte Land um den Blackrock und über die Hänge des Vulkans von Un'Goro. Ein Feuerelementar gibt der vertrauten Bewegung eines Brandes eine eigene Richtung und einen eigenen Zweck." }, { "Ragnaros herrscht über die tiefsten Feuer unter dem Blackrock, mit Dienern überall in seinem Reich. Anderswo rufen Schamanen und Beschwörer die Flamme an andere Orte. Das Element bleibt erkennbar, doch seine Gegenwart allein verrät einem Reisenden nicht, wessen Befehl es gehorcht, falls überhaupt jemandes." } } },
    ["forest-trolls"] = { title = "Waldtrolle", note = { { "Die Witherbark, die Vilebranch und die Moosschinder bewohnen Wälder, in denen sich die Überreste älterer Trollherrschaft schichten. Jintha'Alor ist noch immer eine gewaltige Tempelstadt, deren Terrassen das Hinterland emporklettern, statt still darin zu versinken." }, { "Die Amani bekämpften Quel'Thalas lange bevor die heutigen Menschenkönigreiche Gestalt annahmen. Diese alte Feindschaft lebt fort unter Stämmen, deren Geschicke heute sehr verschieden sind. Die Revantusk handeln an der Küste des Hinterlands mit der Horde, während ihre Nachbarn im Landesinneren ihren eigenen Boden halten." }, { "Grüne Haut und Hauer verraten einen Waldtroll schnell genug. Welcher Empfang einen Reisenden erwartet, verraten sie nicht." } } },
    ["furbolgs"] = { title = "Furbolgs", note = { { "Furbolgdörfer gehören zu den alten Wäldern Kalimdors. Totems, Unterkünfte und Schamanen geben ihnen einen Platz unter den Völkern des Waldes, auch wenn ein Reisender, der in ein verderbtes Lager kommt, vielleicht nur dessen Gewalt sieht." }, { "Die Knarzklauen, die Schwarzfelle, die Totenwaldfelle und die Winterfelle haben alle schreckliche Veränderungen erlitten. Die Holzschlundfeste hat sich diesem Schicksal widersetzt und bewacht noch immer ihre Tunnel zwischen dem Teufelswald, Moonglade und Winterspring. Ihr Misstrauen gegenüber Fremden hat reichlich Grund." }, { client = "forever", "Die Schwarzschlundfeste in Azshara gehört einem anderen Stamm. Auch dort hat die Verderbnis Wurzeln geschlagen. Die Holzschlundfeste im Teufelswald sollte nicht die Schuld für das tragen, was hinter dem steinernen Tor liegt." } } },
    ["giants"] = { title = "Riesen", note = { { "Meeresriesen schreiten die Küsten Kalimdors entlang, und große Klippengänger bevölkern die Höhen von Azshara und Feralas. Vor einer fernen Landzunge ist ihre Größe schwer einzuschätzen. Ein Baum oder eine zerfallene Säule neben ihnen liefert das fehlende Maß." }, { "Überlieferungen verbinden die Riesen der Welt mit ihrer uralten Gestaltung. Die Liga hat über die verschiedenen Arten noch vieles festzustellen. Für einen Vermesser sind selbst ihre Spuren beachtliche Geländemerkmale, und ein lebendes Exemplar kann eine sehr weite Aussicht unterbrechen." } } },
    ["gnolls"] = { title = "Gnolle", note = { { "Gnolllager drängen sich um Minen, Felder und schlecht bewachte Straßen. Die Zelte der Flusspfoten in Elwynn und Westfall, die Hütten der Moosfelle im Sumpfland und die Lager der Waldpfoten in Feralas haben ziemlich denselben praktischen Vorteil: die Vorräte anderer Leute in Reichweite." }, { "Ihre Rudel haben Anführer, Zauberwirker und Plünderer und können eine Siedlung ernsthaft unter Druck setzen. Hoggers Ruf ist weit über sein Stück Elwynn hinausgedrungen. Für einen Gnoll ist das eine ungewöhnliche Auszeichnung, auch wenn die Leute, die sein Kopfgeld zahlen, sie gern beendet sähen." } } },
    ["goblins"] = { title = "Goblins", note = { { "Die Goblins, die hier verzeichnet sind, begegnen einem eher auf dem Boden einer Werkstatt oder einem Schlachtfeld als an einem Ladentisch. Van Cleef hat Ingenieure in den Todesminen, und gefährliche Erfindungen tauchen überall dort auf, wo ihre Erbauer Platz zum Arbeiten finden." }, { "Ein Schredder oder eine angeheuerte Wache verrät etwas über die Mittel hinter einem kleinen Goblinlager. Ein Großteil des Kämpfens erledigt vielleicht etwas, das der Ingenieur gebaut, gekauft oder zum Vorangehen überredet hat. Die Statur des Erfinders ist ein schlechtes Maß für die Größe des Unternehmens." } } },
    ["gorillas"] = { title = "Gorillas", note = { { "Die Gorillas des Schlingendorntals, von Feralas und Un'Goro haben die Masse, um in einem vollen Dschungel aufzufallen. Silberrücken, Nebeltalgorillas und die großen Donnerer unterscheiden sich in der Größe, doch selbst die kleineren lassen die Baumstämme um sie herum schlank aussehen." }, { "Die Namen verraten etwas von dem Eindruck, den sie hinterlassen: König Mukla, Uhk'loc, U'cha. Jäger ziehen los, um ein bestimmtes Tier zu suchen, und kehren mit einem Namen zurück, der nach einem Herrscher klingt. Ein Gorilla braucht weder Krone noch Thron, um eine Lichtung gründlich in Beschlag zu nehmen." } } },
    ["great-cats"] = { title = "Großkatzen", note = { { "Die Großkatzen schenken einem Wald viel von seiner Stille. Das dunkle Fell eines Nachtsäblers verschwindet zwischen den Bäumen Teldrassils, ein Frostsäbler gehört in den Schnee von Winterspring, und ein Panther des Schlingendorntals kann bei hellem Tageslicht bemerkenswert schwer auszumachen sein." }, { "Das Band der Nachtelfen mit ihren Säblern zeigt eine andere Seite dieser Jäger: Gefährten und Reittiere ebenso wie Raubtiere. Jenseits der abgerichteten Tiere dient dieselbe Anmut dem Geschäft der Jagd. Ein Tiger, der einen sonnigen Pfad überquert, ist ein schöner Anblick, so kurz er auch dauert." } } },
    ["great-saurians"] = { title = "Teufelssaurier und die Tiere von Un'Goro", note = { { "Un'Goro hat Platz für Geschöpfe, neben denen die meisten anderen Wälder beengt wirken würden. Teufelssaurier schreiten über das Unterholz hinweg, Stegodons tragen große Platten auf dem Rücken, und Pterrordaxe kreisen über dem Kraterrand. Ein Dimetrodon an den heißen Quellen kann in solcher Gesellschaft fast bescheiden wirken." }, { "Die Expedition von Marshal hat diesen Tieren Namen und einen Platz in ihren Berichten gegeben. Der Krater gibt ihnen den Rest: dichtes Grün, dampfenden Boden und Raum genug, damit ein Teufelssaurier hinter dem nächsten Baumbestand verschwinden kann. Ihn zu vermessen ist ein beträchtliches Unterfangen." } } },
    ["green-dragonflight"] = { title = "Der grüne Drachenschwarm", note = { { "Yseras grüner Schwarm bewacht den Smaragdgrünen Traum, doch der Nachtmahr hat einige seiner eigenen Wächter erreicht. Die Drachkin an den großen Portalen in Ashenvale, Feralas, im Hinterland und im Dämmerwald machen diese Gefahr in der wachen Welt sichtbar." }, { "Eranikus' Schemen spukt im Versunkenen Tempel, und andere mächtige Drachen sind verändert aus dem Traum hervorgegangen. Die großen Bäume um die Portale bleiben schön. Gerade das macht die Verderbnis so verstörend: Der Eingang zu einem Ort des Lebens hat so gequälte Wächter bekommen." } } },
    ["grimtotem"] = { title = "Die Grimmtotem", note = { { "Die Lager der Grimmtotem besetzen beherrschenden Boden: den Düsterwolkengipfel über Tausend Nadeln, ein Truppenlager in Feralas und Besitzungen weiter drüben in Kalimdor. Ihre Krieger und Schamanen haben die Stärke anderer Tauren, gerichtet gegen Nachbarn, die oft ihre Abstammung teilen." }, { "Magatha Grimmtotem hat einen Platz unter den Ältesten von Thunder Bluff, auch während der Ehrgeiz ihres Stammes ihn gegen Cairnes Weg stellt. Die vertrauten Totems und Zelte können ein feindliches Lager trügerisch wie eine Zuflucht von der Straße aussehen lassen." } } },
    ["harpies"] = { title = "Harpyien", note = { { "Harpyien nisten über den Zugängen zu den Siedlungen anderer Leute. Die Horste der Staubschwingen in Durotar, die Höhen der Windfurien in Mulgore und die Nester der Hexenschwingen im Brachland verschaffen allesamt den Flügeln den Vorteil gegenüber einer Karawane." }, { "Ihre Krallen sind nur ein Teil der Gefahr. Sturmhexen fügen dem Kreischen eines aufgestörten Schwarms Zauber hinzu. Ein Nest hoch an einer Klippe ist ein schwieriger Ort, um dort Fragen zu stellen. Ein Großteil dessen, was die Liga über Harpyien weiß, wurde deshalb vom Boden darunter aus gesammelt." } } },
    ["hostile-elves"] = { title = "Feindselige Elfen", note = { { "Eine elfische Expedition zwischen den Ruinen sucht vielleicht dasselbe wie die Liga: eine Inschrift, ein Relikt, ein erhaltenes Stück uralter Handwerkskunst. In Azshara macht die Jagd der Blutelfen nach verlorener arkaner Macht dieses gemeinsame Interesse zu einer schlechten Gewähr für einen freundlichen Empfang." }, { "Düsterbruch hat seine eigenen gefährlichen Schüler der Magie, Lethtendris unter ihnen. Die alten Städte bergen noch immer Macht, die es zu suchen lohnt, und wer sie erreicht, lässt nicht immer Platz für einen zweiten Gelehrten." } } },
    ["hydras"] = { title = "Hydren", note = { { "Eine Hydra kündigt sich gleich mit mehreren Köpfen an. Die langen Hälse erheben sich aus Küstengewässern oder einem Höhlenteich, sodass schwer zu entscheiden ist, welches Augenpaar zuerst Aufmerksamkeit verdient." }, { "Die Mythosschuppen heimsuchen Kalimdors Küsten, während andere Hydren tief in Maraudon hausen. Gahz'rilla hat einen heiligen Teich in Zul'Farrak und die Verehrung der Sandwüter. Die meisten Geschöpfe in diesem Buch müssen sich mit einem Futterplatz begnügen. Dieses hat sich eine Gemeinde zugelegt." } } },
    ["hyenas"] = { title = "Hyänen", note = { { "Hyänen passen zu trockenem Land: hagere Gestalten vor dem Staub des Brachlands, von Tanaris und Desolace. Ihre Rufe verraten sie, selbst wenn das Gras oder eine Bodenfalte das Rudel verbirgt." }, { "Die Namen, die man ihnen gibt, sind selten liebevoll. Kicherfang, Eiterpfote, verhungernde Hyäne: Reisende erinnern sich an den Laut, die Zähne oder den Zustand des Tieres, das ihnen folgte. In dem letzten Namen steckt ein ganzes schweres Leben, draußen, wo eine Mahlzeit nie sicher ist." } } },
    ["ice-trolls"] = { title = "Eistrolle", note = { { "Die Frostmane kennen Dun Morogh als Heimat und nicht als Weg nach Ironforge. Ihre Höhle westlich von Kharanos und ihre Lager im Schnee liegen nah an den zwergischen Siedlungen, die sie aus einem Großteil des Tals vertrieben haben." }, { "Kopfjäger, Seher und Schattenzauberer verteidigen, was sie noch besitzen. Für einen jungen Zwerg sind sie oft die ersten Trollfeinde, denen er begegnet. Für die Frostmane ist der Zwerg ein weiterer Ankömmling aus der Stadt oben. Derselbe verschneite Pass trägt zwei sehr verschiedene Berichte darüber, wer dorthin gehört." } } },
    ["insects"] = { title = "Insekten", note = { { "Nicht jedes große Insekt gehört zu einem Silithidenstock. Käfer und Skarabäen bewohnen die Wüsten und alten Ruinen aus eigenem Recht, auch wenn ihre Größe einen Reisenden manchmal eher zur Waffe als zum Notizbuch greifen lässt." }, { "In Zul'Farrak bewegen sich Skarabäen zwischen dem Mauerwerk und den Grabstätten der Sandwüter. Vor einer Tempelwand wirken sie wie eine kleine Einzelheit. Um die eigenen Stiefel versammelt, beanspruchen sie weit mehr Aufmerksamkeit." } } },
    ["jungle-trolls"] = { title = "Dschungeltrolle", note = { { "Die Trollruinen des Schlingendorntals sind bewohnte Geschichte. Die Stämme der Bloodscalp und der Skullsplitter kämpfen zwischen den alten Steinen, während Zul'Gurub ein Zentrum der Macht der Gurubashi bleibt. Seine Hohepriester haben Hakkar in die Welt zurückgeholt." }, { "Die Atal'ai tragen die Verehrung des Blutgottes auch in den Versunkenen Tempel. Andere Dschungeltrolle haben einen anderen Weg eingeschlagen: Die Dunkelspeer gehören zu Thralls Horde, und die Insel Yojamba beherbergt die Bemühungen der Zandalari gegen Hakkar. Ein altes Reich hat viele Erben hinterlassen, mit sehr verschiedenen Absichten." } } },
    ["kobolds"] = { title = "Kobolde", note = { { "Ein Licht in einer verlassenen Mine gehört oft einem Kobold. Ihre Kerzen markieren die Stollen von Elwynn und Westfall, wo schmale Gänge es einem kleinen Gräber erlauben, sich ganz groß lästig zu machen." }, { "Der vertraute Protest, \"Du nicht nehmen Kerze!\", ist in der Sache, um die es gerade am dringendsten geht, recht deutlich. Darüber hinaus erzählt die Kerze eine praktische Geschichte: Jemand hat vor, im Dunkeln zu arbeiten und zu leben. Für den Bergmann, der wegen seines Schürfrechts zurückkommt, ist der Stollen besetzt. Für den Kobold ist der Bergmann ein Eindringling." } } },
    ["kodos"] = { title = "Kodos", note = { { "Kodoherden geben den offenen Ebenen einen langsamen, schweren Rhythmus. Die Tauren reisen und kämpfen an der Seite dieser großen Tiere, und ein beladener Kodo ist ein vertrauter Anblick, wo immer die Horde einen langen Weg zurückzulegen hat." }, { "Desolace birgt eine seltsamere Versammlung: den Kodofriedhof, wo alte Tiere kommen, um zwischen den Knochen ihrer Art zu sterben. Die lebenden Herden sind beeindruckend, doch diese gewaltigen Überreste geben ein anderes Maß für sie. Ein Geschöpf, das so sehr zu einer ziehenden Karawane gehört, kann einen sehr stillen Ort hinterlassen." } } },
    ["leper-gnomes"] = { title = "Lepragnome", note = { { "Der Fall Gnomeregans hat nicht jeden Überlebenden nach Ironforge geschickt. Die Strahlung hat manche, die in der Stadt blieben, an Leib und Geist verändert, und die Lepragnome bewohnen noch immer ihre Zugänge und die maschinengefüllten Hallen." }, { "Ihre grüne Haut macht den Schaden sofort sichtbar. Die vertraute gnomische Kleidung und das vertraute Werkzeug machen es schwerer, seine Bedeutung beiseitezuschieben. Für die Verbannten birgt die alte Stadt Nachbarn ebenso wie die Dinge, die sie vertrieben haben." } } },
    ["living-plants"] = { title = "Lebende Pflanzen und Uralte", note = { { "Ein Wald kann sich ohne einen Windhauch bewegen. Treants und Uralte geben den Wäldern der Nachtelfen ihre großen wandelnden Gestalten, während Peitscher und Ranken den Boden viel näher an den Stiefeln eines Reisenden besetzen." }, { "Manche verteidigen einen lebendigen Wald. Andere wurden von der Verderbnis verändert. Die Bäumlinge Teldrassils und das Gewächs in Düsterbruch verdienen unterschiedliche Berichte, selbst wenn beide einen Pfad schwer passierbar machen." }, { "Der Sumpf hat seine eigenen Formen wandelnder Pflanzen und wandelnden Schlamms. Wurzeln, Äste und eine vertraute grüne Farbe sind nur der Anfang, wenn man bestimmen will, was sich daraus erhoben hat." } } },
    ["lost-ones"] = { title = "Die Verirrten", note = { { "Die Draenei im sicheren Hafen sind Flüchtlinge aus Draenor, der Welt, aus der die Orcs kamen. Die Verirrten im Fallow Heiligtum teilen diese Herkunft, auch wenn ihre gewalttätige Abgeschiedenheit die Verbindung für einen Reisenden, der den Sumpf durchquert, weniger offensichtlich macht." }, { "Magtoor und seine Gefährten helfen, wo sie können, unter Leuten, die kaum wissen, was sie von ihnen halten sollen. Ihre Gegenwart gibt dem Lager der Verirrten einen traurigeren Zusammenhang: Hier ist ein weiteres Volk weit von der Heimat verstreut, und manche der Seinen finden keine Zuflucht mehr bei den Übrigen." } } },
    ["machines"] = { title = "Golems und Maschinen", note = { { "Ein Erntegolem auf den Feldern von Westfall gehört zu einer anderen Art von Natur. Schredder im Steinkrallengebirge, Kriegsmaschinen in Gnomeregan und die Konstrukte der Dunkeleisenzwerge haben alle in einer Werkstatt begonnen, was auch immer seither aus ihren Anweisungen geworden ist." }, { "Die Absichten ihrer Erbauer können in der Bauweise fortleben: schneidende Arme, Erntezangen, eine Kanone dort, wo ein Tier seinen Kopf hätte. Die Maschine muss sich nicht erklären. Ein Beobachter kann ihren Zweck oft an den Werkzeugen ablesen, die an ihr angebracht sind." } } },
    ["makrura"] = { title = "Makrura", note = { { "Makrura bevölkern die Untiefen Kalimdors auf eine ganz andere Weise als die Krabben neben ihnen. Die aufrechten Körper, die greifenden Scheren und die bewachten Kolonien gehören zu einem Volk, so fremd ihre Sprache und Gestalt auch sein mögen." }, { "An der Küste Durotars begegnen ihnen viele junge Orcs zum ersten Mal. Größere Kolonien liegen weiter die Küste hinab. Ein Strand bietet einem Reisenden, der sich vom Land her nähert, wenig Deckung, und das Wasser hinter einer Siedlung der Makrura muss nicht die Grenze ihrer Bewohner sein." } } },
    ["murlocs"] = { title = "Murlocs", note = { { "Murlocdörfer hinterlassen an einer Küste ein erkennbares Zeichen: niedrige Hütten, Fischernetze und eine Menge Lärm, wenn sich ein Fremder nähert. Ihre Werkzeuge und Siedlungen verdienen mehr Aufmerksamkeit, als ihnen die üblichen Berichte über einen gurgelnden Ansturm schenken." }, { "Sie verteidigen diese Dörfer gemeinsam, was erklärt, warum sich ein Kampf, der mit einem begann, so schnell einen Strand entlang ausbreiten kann. Ihre Sprache ist für die meisten Reisenden schwer zu verstehen. Das ist eine Schwierigkeit der Übersetzung, kein Beweis, dass nichts gesagt wird." } } },
    ["naga"] = { title = "Naga", note = { { "Die Naga bewohnen versunkene Orte, die einst Teil der Welt der Nachtelfen waren: den Zoramstrand, die Ruinen von Azshara und die Küste der Dunkelküste. Ihre schlangenartigen Körper passen nun zu dem Wasser, das das alte Reich der Hochgeborenen bedeckt hat." }, { "Nach dem Dritten Krieg traten sie offen hervor und haben sich seither an vielen Küsten festgesetzt. Meerhexen und bewaffnete Myrmidonen machen daraus mehr als verstreute Strandlager. Zwischen den zerbrochenen Säulen kann es scheinen, als seien sie in eine Stadt zurückgekehrt, deren Straßen nur sie noch nutzen können." } } },
    ["oddities"] = { title = "Seltsame Geschöpfe", note = { { "Manche Begegnungen lassen die Überschriften einer Naturgeschichte unzureichend wirken. Ein einzigartiges Ungeheuer, ein seltsamer Bewohner eines Verlieses oder ein Geschöpf, das ein örtlicher Kult verehrt, hat womöglich nirgendwo sonst im Buch nützliche Verwandte." }, { "Diese Seite bewahrt die einzelne Begegnung unversehrt, solange ihr Platz im größeren Bericht ungewiss bleibt. In einem Forschertagebuch ist Raum für eine offene Frage, besonders für eine, die gerade aus einem See gestiegen ist." } } },
    ["ogres"] = { title = "Oger", note = { { "Oger kamen mit der Horde durch das Dunkle Portal und zerstreuten sich dann in Klans über ganz Azeroth. Ein verfallener Turm oder eine Berghöhle beherbergt heute vielleicht die Felsfäuste, die Crushridge, die Staubspeier oder einen anderen Klan, dessen Name zu einer örtlichen Warnung geworden ist." }, { "Ihre Größe fällt als Erstes auf, doch Ogermagier taugen schlecht für die üblichen Witze über den Verstand der Oger. Zwei Köpfe können eine beachtliche Beherrschung der Magie tragen." }, { "Die Stonemaul in Dustwallow haben sich der Horde angeschlossen. Anderswo muss man die Treue eines Klans für sich allein in Erfahrung bringen. Ein vertrauter Umriss ist keine Vorstellung." } } },
    ["oozes"] = { title = "Schlammwesen und Schleime", note = { { "Ein Schlammwesen hat sehr wenig Gestalt, die einem Naturkundler bei der Beschreibung helfen könnte. Farbe und Beschaffenheit müssen einen Großteil der Arbeit leisten: die Schlämme eines Marschlands, die seltsamen Überreste von Gnomeregans Katastrophe, der wandernde Unrat vergifteten Wassers." }, { "Manche hinterlassen die Reste dessen, was sie verschluckt haben, eine unappetitliche, aber nützliche Aufzeichnung ihrer Umgebung. Neben einem großen Tier oder einem wandelnden Baum übersieht man sie leicht. Ein Fleck Schleim, der sich hangaufwärts bewegt, hat seinen eigenen Anspruch auf das Notizbuch." } } },
    ["other-beasts"] = { title = "Andere Tiere", note = { { "Es gibt Tiere, bei denen eine ordentliche Familienüberschrift mehr verspräche, als die Belege hergeben. Eine ungewöhnliche Gestalt, ein einzelnes Exemplar oder ein Geschöpf, das man vor allem vom Namen auf einem Jagdauftrag kennt, kann hier seinen Platz finden." }, { "Ein weit gefasster Katalog ist nützlich, bis er das Tier darin verbirgt. Diese Aufzeichnungen lassen Raum für das Einzelne: wo es angetroffen wurde, wie es aussah und was es vom letzten angeblich einzigartigen Ungeheuer unterscheidet." } } },
    ["other-dragonkin"] = { title = "Andere Drachkin", note = { { "Die Farbe eines Drachen bietet gewöhnlich einen Anfang für seine Geschichte. Weniger hilfreich ist sie bei einem unbekannten Exemplar oder bei den gemischten Drachkin aus Nefarians Experimenten in der Blackrockspitze." }, { "Solche Geschöpfe werden hier verzeichnet, bis es einen triftigen Grund gibt, sie anderswo einzuordnen. Ein ordentlicher Katalog sollte eine schwierige Bestimmung nicht verbergen, besonders wenn das fragliche Geschöpf groß genug ist, um gegen die Verzögerung Einspruch zu erheben." } } },
    ["other-elementals"] = { title = "Andere Elementare", note = { { "Die vertraute Einteilung in Erde, Luft, Feuer und Wasser erklärt nicht jede Begegnung. Manche belebten Wesen und ungewöhnliche elementare Gestalten gelangen auf diese Seite, ohne einen klaren Platz unter den anderen." }, { "Ihre Umgebung liefert oft den besten Anfang: die Kammer eines Beschwörers, eine uralte Halle oder ein seltsames Stück offenen Landes. Die Aufzeichnung kann diese Einzelheiten bewahren, selbst wo die Natur des Bewohners ungeklärt bleibt." } } },
    ["other-peoples"] = { title = "Andere Humanoide", note = { { "Manche Gegner verzeichnet man am besten nach dem Ort und der Gesellschaft, in der man ihnen begegnet ist. Ein einsamer Gesetzloser, die Wache eines Verlieses und ein abtrünniger Magier mögen ein Volk teilen, ohne eine Sache zu teilen." }, { "Diese Seiten halten ihre Begegnungen beisammen, ohne ihnen ein Banner anzudichten. Ein Name, eine Waffe und ein Lager sind bescheidene Anfänge für einen Bericht, doch sie sind besser, als einen unbekannten Menschen im Wort \"Feind\" verschwinden zu lassen." } } },
    ["other-undead"] = { title = "Andere Untote", note = { { "Die Seuche von Lordaeron erklärt nicht jeden wandelnden Leichnam. Im Dämmerwald gibt es Gräber, die andere Hände aufgewühlt haben, und alte Flüche oder das Werk eines Nekromanten können Tote weit entfernt von den Heeren der Geißel in Bewegung halten." }, { "Ein Name kann hier besonders wertvoll sein. Die Überreste haben die Erklärung womöglich überdauert, während ein Dorfregister oder ein überlebender Verwandter sie noch bewahrt. Das Geschöpf auf dem Friedhof und der Mensch im Bericht sind manchmal derselbe Gegenstand, von entgegengesetzten Enden einer Geschichte her betrachtet." } } },
    ["owls"] = { title = "Eulen", note = { { "Eine Eule findet man oft am leichtesten an ihren Augen. Die Strigideulen Teldrassils sitzen in einem Wald, der ohnehin voll nachtelfischer Wachsamkeit ist, während die großen Eulen von Winterspring blass vor den dunklen Bäumen hervortreten." }, { "Die Eisenschnäbel des Teufelswalds gehören zu einem beschädigten Wald und teilen seine Gefahren. Anderswo bleibt Raum, die Stille eines sitzenden Vogels zu würdigen, bevor sich die Flügel öffnen. Die Wälder enthalten genug Lärm. Eine Eule ist eine vorzügliche Studie seines Fehlens." } } },
    ["pirates"] = { title = "Piraten", note = { { "Ein Piratenlager hat viel von einem Hafen: Schiffe, Vorräte und Seeleute mit Arbeit. Der Unterschied wird deutlich, wenn ein Schiff der Blutsegelbukaniere auf Booty Bay zuhält oder Mannschaften der Südmeerfreibeuter eine weitere Ladung für sich beanspruchen." }, { "Ihre Festungen säumen die warmen Küsten, von der Händlerküste bis Tanaris. Der Goblinhandel hat diese Gewässer belebt genug gemacht, um sowohl Händler als auch die Leute zu ernähren, die sie ausrauben. Von einer fernen Landzunge aus können die Segel einander sehr ähnlich sehen." } } },
    ["quilboar"] = { title = "Stacheleber", note = { { "Die gewaltigen Dornen des Brachlands sind die Heimat der Stacheleber. Ihre Überlieferungen nennen Agammagan ihren Ahnen, und die Gegenwart des gefallenen Halbgottes gehört zum Land ebenso wie zu ihren Riten." }, { "Die Lager der Grimmhauer, der Borstennacken und von Razorfen verteidigen dieses Land gegen Tauren, Zentauren und die neue Horde. Ihre Schamanen geben den dornigen Siedlungen eine andere Art von Stärke. In den Hügeln von Razorfen haben Geschäfte mit der Geißel den Stamm der Totenköpfe in eine dunklere Gefolgschaft geführt." }, { "Ein Außenstehender sieht eine Wand aus Dornengestrüpp. Dahinter liegen Heimstätten, rivalisierende Stämme und eine Geschichte, die älter ist als die vorbeiführende Straße." } } },
    ["rams-and-goats"] = { title = "Widder und Ziegen", note = { { "Ein Widder wirkt auf einem Boden völlig zu Hause, auf dem ein Zwerg über die Güte seiner Stiefel nachdenkt. Dichtes Vlies und gebogene Hörner sind in ganz Khaz Modan vertraut, und die Tiere, die von Ironforge aus geritten werden, haben wilde Verwandte in denselben Bergen." }, { "Auch die Stormpike greifen im Alteractal auf Widder zurück. Zwischen einem Bergpfad und einem Schlachtfeld wird viel vom Tritt eines Reittiers verlangt. Der Widder begegnet beidem mit der Miene eines Tieres, das den Boden bereits für zufriedenstellend befunden hat." } } },
    ["raptors"] = { title = "Raptoren", note = { { "Ein Raptor besteht aus Hinterbeinen, Schwanz und Zähnen, nach ganz anderen Linien gebaut als ein Wolf oder eine Katze. Die Blutkrallen von Durotar und die Bluthörner des Brachlands sind vertraute Beispiele. Größere Arten jagen durch das Sumpfland und die Dschungel des Südens." }, { "Trollreiter haben sie zu Gefährten gemacht, ein Brauch, der großes Vertrauen in das Tier im eigenen Rücken verlangt. In der Wildnis kann der schmale Umriss eines Raptors im Schilf verschwinden, bis er sich umdreht. Der Kopf ist meist das Erste, woran sich ein Reisender erinnert." } } },
    ["red-dragonflight"] = { title = "Der rote Drachenschwarm", note = { { "Rote Welpen bewohnen noch immer das Sumpfland, wo die größeren Mitglieder von Alexstraszas Schwarm Grim Batol bewachen. Der Berg hielt einst ihre Königin gefangen, in der Gewalt der Orcs der Dragonmaw, die ihre Nachkommen im Zweiten Krieg einsetzten." }, { "Ihre Befreiung beendete diese Gefangenschaft, ohne Grim Batol zu einem einladenden Ort zu machen. Rote Drachkin halten nun seine Zugänge gegen Fremde. Für einen Schwarm, dem der Schutz des Lebens anvertraut ist, tragen diese bewachten Tore eine lange und bittere Erinnerung." } } },
    ["restless-spirits"] = { title = "Geister und ruhelose Seelen", note = { { "Nicht jeder Geist in Azeroth dient der Geißel. Manche sind Seelen, die nie Ruhe gefunden haben: die Hochgeborenen, die in ihren zerfallenen Türmen an der Dunkelküste und in Azshara spuken, die Ertrunkenen und die Ermordeten, die Krieger, die fern der Heimat fielen und noch immer umherwandern." }, { "Manche sind nur traurig. Manche sind zornig, und der Zorn ist alles, was von ihnen übrig ist. Einige sprechen, wenn man zuhört." }, { "Die Liga verzeichnet sie mit Sorgfalt. Sie sind schließlich die ältesten Zeugen, die wir haben." } } },
    ["sand-trolls"] = { title = "Sandtrolle", note = { { "Zul'Farrak erhebt sich noch immer als Stadt über den Sand, trotz all der Verwüstung ringsum. Die Sandfury verteidigen ihre Terrassen und heiligen Teiche gegen eine Wüste, in der sich Goblins, Banditen und Abenteurer immer mehr drängen." }, { "Gahz'rilla wird dort verehrt, und die Gräber haben Wächter, die nicht tot geblieben sind. Die Stadt ist ein schlechter Ort, um jeden alten Stein als verlassenes Relikt zu betrachten. Die Nachfahren ihrer Erbauer sind durchaus in der Lage, den Anspruch eines Besuchers darauf zu bestreiten." } } },
    ["satyrs"] = { title = "Satyrn", note = { { "Ein Satyrlager ist eine Wunde in einem alten Wald. Gehörnte Gestalten bewegen sich zwischen kranken Bäumen, und die Nachtelfen, die sich ihnen entgegenstellen, kämpfen gegen Geschöpfe, deren Geschichte in ihrem eigenen Volk begann." }, { "Xavius, der Berater Königin Azsharas, war der erste der Satyrn, von Sargeras während des uralten Krieges neu geformt. Seinesgleichen dient der Verderbnis noch immer in Ashenvale und im Teufelswald. Zehntausend Jahre sind vergangen, und doch verliert der Wald um ihre Lager herum noch immer an Boden." } } },
    ["scarlet-crusade"] = { title = "Der Scharlachrote Kreuzzug", note = { { "Die roten Banner des Scharlachroten Kreuzzugs markieren einige der stärksten verbliebenen Stellungen der Menschen in Lordaeron: das Kloster, Hearthglen, Tyrs Hand und einen Teil von Stratholme. Priester, Paladine und Soldaten halten diese Mauern gegen die Untoten." }, { "Ihr Misstrauen reicht weit über die Geißel hinaus. Fremde werden womöglich als Träger der Seuche oder als verkleidete Feinde behandelt, und die Verlassenen haben keinen Platz in ihrer Vorstellung eines wiederhergestellten Königreichs. Ein Reisender kann hinter den Barrikaden lebende Verteidiger finden, ohne dort Zuflucht zu finden." } } },
    ["scorpids"] = { title = "Skorpide", note = { { "Skorpide nutzen trockenen Boden bemerkenswert gut. Ihre flachen Panzer verschmelzen mit der roten Erde Durotars und dem Staub der südlichen Wüsten, während der erhobene Schwanz einen beunruhigenden Augenblick später sichtbar wird." }, { "Ihr Gift und ihr Panzer haben beide ihren Nutzen, und so ziehen junge Jäger los, um Geschöpfe zu suchen, vor denen ihre Älteren sie gewarnt haben. Die Orcs von Durotar kennen Skorpidpanzer gut. Ein zum Studium ausgelegtes Exemplar ist ein stattliches Stück natürlicher Rüstung, mit Gelenken, die einen genauen Blick lohnen." } } },
    ["scourge"] = { title = "Die Geißel", note = { { "Die Geißel macht aus einer Bevölkerung ein Heer: Skelette, Ghule, Seuchenopfer und zusammengenähte Monstrositäten füllen die Straßen und Ruinen von Lordaeron. Ihre Nekromanten fügen neue Soldaten hinzu, wo immer sich Leichen finden." }, { "Scholomance und Stratholme sind große Zentren dieses Werks, während die Hügel von Razorfen zeigen, wie weit sein Einfluss reicht. Die Toten brauchen weder Ernte noch Ruhe, und das Land, das sie besetzen, verliert stetig das Leben, das es einst trug." }, { "Zwischen den Knochen und zerrissenen Kleidern liegen die Überreste gewöhnlicher Bewohner. Das Heer hat für ihre alten Berufe keine Verwendung, doch ein Forschertagebuch kann sie noch würdigen." } } },
    ["servants-of-the-firelord"] = { title = "Diener des Feuerlords", note = { { "Die Feuerschuppen des Geschmolzenen Kerns sind unverkennbar Diener von Ragnaros: bewaffnete Gestalten mit schlangenartigem Unterleib, zu Hause zwischen den Feuern unter dem Blackrock. Lucifron, Gehennas, Shazzrah und ihresgleichen bewachen die Zugänge zum Feuerlord." }, { "Hier ist die Hitze des Berges Teil eines bewohnten Reiches. Was ein Zwerg für einen unmöglichen Ort zum Bauen halten mag, enthält Wachen, Befehlshaber und den Sitz eines Herrn. Das Fehlen bequemen Bodens ist ganz und gar das Problem des Besuchers." } } },
    ["shadow-council"] = { title = "Der Schattenrat", note = { { "Der Schattenrat half, die alte Horde an die Legion zu binden. Sein fortbestehender Einfluss zeigt sich heute an Orten wie Jaedenar, wo Kultisten und Dämonen denselben verderbten Boden besetzen." }, { "Thralls Horde hat diese Herren verworfen, doch die Beschwörungskreise bleiben. Um sie versammeln sich Anhänger aus mehr als einem Volk und betreiben Künste, deren Preis bereits quer über den Teufelswald geschrieben steht. Die geschwärzten Bäume sind eine nützliche Begleitung zu allen Versprechen, die im Lager gemacht werden." } } },
    ["sharks-and-fish"] = { title = "Haie und Fische", note = { { "Die Oberfläche eines Sees verrät sehr wenig über seine Bewohner. Loch Modan hat seine Lochfrenzys. Die Küsten haben Dreschadons und Haie, groß genug, um den Blick aus einem Boot besonders willkommen zu machen." }, { "Das sind die Fische, denen ein Angler unangenehm nah begegnet. Eine Flosse im offenen Wasser ist nur ein Bruchstück des Geschöpfs darunter, und ein Schwarm kann einen ruhigen Teich in plötzliche Bewegung versetzen. Das Buch des Lebens unter der Oberfläche ist dick. Diese Seite behandelt seine bissigeren Abschnitte." } } },
    ["silithid"] = { title = "Silithiden und Qiraji", note = { { "Die Stöcke der Silithiden verändern die Gestalt der südlichen Wüsten. Hügel erheben sich über Tunneln, in denen Wespen, Arbeiter und große gepanzerte Krieger hausen. Die Oberfläche bietet nur einen unvollständigen Blick auf die Bevölkerung darunter." }, { "Die Qiraji von Ahn'Qiraj befehligen diese Schwärme. Vor tausend Jahren endete der Krieg der Treibsande damit, dass Nachtelfen und Drachen die Heere hinter dem Skarabäuswall versiegelten." }, { "Die Stöcke jenseits dieses Walls machen den alten Krieg zu einer Sorge der Gegenwart. Ein flacher Hügel am Horizont kann einen viel größeren Anspruch unter dem Sand markieren." } } },
    ["snakes"] = { title = "Schlangen", note = { { "Eine Schlange kann sehr wenig von der Aufmerksamkeit eines Reisenden beanspruchen, bis sie den Pfad kreuzt. Zusammengerollt verrät ihr Körper kaum etwas über ihre Länge, und ein erhobener Kopf lässt ein bescheidenes Stück Boden gründlich in Besitz genommen wirken." }, { "Die Schlangen der Höhlen des Wehklagens sind vom Albtraum dort verändert worden. In Zul'Gurub haben Schlangen einen Platz in der Verehrung des Blutgottes. Beide Schauplätze geben dem Naturkundler mehr zu bedenken als Schuppen und Gift, auch wenn diese allein schon reichlich Stoff bieten." } } },
    ["spiders"] = { title = "Spinnen", note = { { "Netze teilen eine Höhle in einen Raum, den ein Reisender sehen kann, und einen Raum, der bereits besetzt ist. In den Minen von Elwynn und im Revier der Waldweber auf Teldrassil sind die Spinnen selbst oft groß genug, um zu erklären, warum ein vertrauter Pfad still geworden ist." }, { "Giftbeutel und Seide machen Apotheker und Handwerker auf sie aufmerksam. Die Seide ist ein besonders feiner Stoff, wenn man sie über eine verlassene Türöffnung gespannt findet. Ihr Hersteller braucht keinen Webstuhl und hat kein Interesse daran, wozu das fertige Werk verwendet wird." } } },
    ["stags-and-steeds"] = { title = "Hirsche, Renner und Weidetiere", note = { { "Zhevras und Giraffen gehören zum weiten Blick über das Brachland, während die Hirsche von Ashenvale zwischen den Stämmen alter Bäume erscheinen. Ihre unterschiedlichen Umrisse helfen einem Reisenden, das Land zu lesen, bevor es ein Wegweiser tut." }, { "Jäger schätzen ihr Fleisch und ihre Häute, doch Ogtinc in Azshara hat ein anderes Interesse an den Mooshufrennern. Er sieht im unversehrten Geweih den Geist eines selbstbewussten Tieres und verlangt ein vollkommenes Paar. Die eindrucksvolle Krone ist zugleich die Waffe, mit der sich der Renner verteidigt, was ein unbeschädigtes Exemplar schwer zu beschaffen macht." } } },
    ["syndicate"] = { title = "Das Syndikat", note = { { "Das Syndikat besetzt die Überreste der Macht Alteracs: verfallene Siedlungen in den Bergen, Stellungen bei Burg Durnholde und einen Fuß in der Tür von Stromgarde. Enteignete Adlige und angeheuerte Verbrecher sind ein unbehaglicher Ersatz für ein Königreich." }, { "Ihre Lager haben noch immer Offiziere und Ehrgeiz, selbst wenn ihre Arbeit auf Raub hinausläuft. Ein gefallener Lord kann seinen Titel lange behalten, nachdem er die Mittel verloren hat, danach zu leben. In den Vorbergen wird der vorbeiziehende Reisende vielleicht gebeten, den Unterschied auszugleichen." } } },
    ["tallstriders"] = { title = "Schreiter", note = { { "Die Schreiter sind langbeinige, langhalsige Vögel der offenen Ebenen, und die Ebenenschreiter von Mulgore und dem Brachland sind nach dem Kodo der vertrauteste Anblick des Graslands. Sie sind recht harmlos, bis man sie in die Enge treibt, und dann treten sie hart genug zu, um einen Schild zu zerbrechen." }, { "Die Tauren jagen sie wegen ihres Fleisches und ihrer Federn, mit dem Dank, den die Erdenmutter von ihnen verlangt. Die Nachtelfen der Dunkelküste und des Teufelswalds kennen einen Vetter aus dem Wald, den Waldschreiter." }, { "Ihre Eier sind begehrt. Ihre Mütter wissen das." } } },
    ["thunder-lizards"] = { title = "Donnerechsen", note = { { "Eine Donnerechse trägt die Überraschung eines Gewitters in einem schweren, vierbeinigen Körper. Die Donnerköpfe des Brachlands und die großen Tiere von Desolace können wie gewöhnliches Weidevieh aussehen, bis ein Blitz den Unterschied deutlich macht." }, { "Ihre Masse ist auch ohne diese Zugabe eindrucksvoll. Die kleineren Klippenstürmer des Steinkrallengebirges teilen dieselbe beunruhigende Verbindung zum Donner. Ein klarer Himmel über dem Pass ist keine Gewähr für eine ruhige Überquerung." } } },
    ["troggs"] = { title = "Troggs", note = { { "Troggs sind aus den tiefen Orten nach Dun Morogh, Loch Modan und Gnomeregan hervorgekommen. Ihre Stärke ist offensichtlich genug. Ihre Verbindung zur Geschichte der Zwerge war eine weit weniger willkommene Entdeckung." }, { "Die Aufzeichnungen in Uldaman beschreiben eine frühere Formung von Stein zu Leben, gefolgt von den Irdenen, von denen die Zwerge abstammen. Diese Aufzeichnungen machen den Trogg zu einem Gegenstand für die Liga ebenso wie zu einem Feind an der Grabungsstätte." }, { "So kann dieselbe Ausgrabung die Geschichte eines Ahnen und einen sehr wütenden Bewohner zutage fördern. Die Archäologie ordnet ihre Gegenstände selten bequem an." } } },
    ["turtles"] = { title = "Schildkröten", note = { { "Der Panzer einer Schildkröte lässt den Rest des Geschöpfs wie einen nachträglichen Einfall wirken, bis der Kopf hervorkommt. Schnappkiefer bewohnen Seen und Flüsse. Die großen Küstenschildkröten von Tanaris und Azshara tragen dieselbe robuste Bauweise ins Salzwasser." }, { "Ihre Geduld lässt sich vom Ufer aus leicht bewundern. Aus der Nähe verdient der Schnabel ebenso viel Aufmerksamkeit. Zwischen beidem sitzt ein Tier, das bemerkenswert gut dafür gerüstet ist, ein Stück Wasser zu bewohnen, ohne sich dabei sichtlich anzustrengen." } } },
    ["twilights-hammer"] = { title = "Der Twilight-Hammer", note = { { "Der Twilight-Hammer ist von einem Orcklan zu einem Kult mit Anhängern vieler Völker angewachsen. Seine Lager sammeln sich um alte Mächte: in der Blackfathom-Tiefe, bei dunklen Götzenbildern und überall im elementaren Land von Silithus." }, { "Die Schriften des Kults sehen dem Ende der Welt entgegen, und seine Beschwörer arbeiten daran, es zu beschleunigen. Roben und gelehrtes Beiwerk können den Lagern den Anschein des Studiums geben. Die beschworenen Elementarfürsten erklären, wozu die Studien dienen." } } },
    ["venture-company"] = { title = "Die Venture Co.", note = { { "Die Werke der Venture Co. sind oft vor ihren Arbeitern zu sehen: ein kahl geschlagener Hang im Steinkrallengebirge, Öl im Brachland, eine Mine, in die Klippen von Mulgore geschnitten. Schredder, Bohrer und angeheuerte Wachen folgen dem Claim." }, { "Goblins organisieren einen Großteil der Arbeit, auch wenn die Arbeitskraft und die Muskeln von mehreren Völkern kommen. Für die Siedlungen in der Nähe ist die Gesellschaft weniger eine ferne Sorge als ein wachsendes Loch oder eine zurückweichende Baumgrenze. Ihre Bücher mögen dem Holz einen Wert beimessen. Der leere Hang lässt sich schwerer beziffern." } } },
    ["water-elementals"] = { title = "Wasserelementare", note = { { "Ein Wasserelementar gibt einer Quelle oder einem Teich einen beweglichen Bewohner aus ihrem eigenen Stoff. Eis ist derselbe Stoff, gefroren, und seine Elementare gehören ebenfalls hierher. Die beschmutzten Elementare von Ashenvale tragen die Verderbnis ihres Waldes in diese vertraute Gestalt." }, { "Vor Azshara verfolgen die Hydraxianer einen ganz anderen Zweck: Sie stellen sich Ragnaros und seinen Dienern entgegen. Auch Magier beschwören Wasserelementare. Eine Welle, die sich zu einem Leib erhebt, ist ein eindrucksvoller Anblick, doch es braucht etwas vom Ort und seiner Geschichte, um zu erklären, warum sie dort ist." } } },
    ["wendigos"] = { title = "Wendigos", note = { { "Die Wendigos von Dun Morogh bewohnen verschneite Höhlen wie den altgedienten Bau, wo weißes Fell vor dem Schnee verschwindet. Die Größe ihrer Hände ist weniger leicht zu übersehen." }, { "Ihre Häute und Mähnen sind vertraute Ziele der Jagdaufträge vor Ort. Einem jungen Zwerg können die Hügel jenseits einer Siedlung wie eine Verlängerung der Heimat erscheinen. Ein Wendigo am Eingang einer Höhle gibt diesen Hügeln einen ganz anderen Maßstab. Nicht jede große Gestalt im Schnee ist ein weiterer Bergsteiger." } } },
    ["wildkin"] = { title = "Wildekin", note = { { "Ein Wildekin hat die Masse eines Bären unter dem Gesicht und dem Gefieder einer Eule, eine Verbindung, die einen stillen Moment der Aufmerksamkeit verdient. Die Nachtelfen halten diese Geschöpfe für Elune heilig." }, { "Moonkin leben an der Dunkelküste, und Eulenbestien bewohnen das Hinterland und Winterspring. Ihre Namen und ihr Wesen sind verschieden, doch die großen runden Augen bleiben unverwechselbar. Ein Wald, in dem eines von ihnen lebt, kann sich beobachtet anfühlen, auf eine Art, die wenig mit dem Hinterhalt eines Jägers zu tun hat." } } },
    ["wind-serpents"] = { title = "Windnattern", note = { { "Windnattern ziehen lange, leuchtende Formen über den Himmel des Brachlands und von Tausend Nadeln. Gefiederte Flügel tragen einen Körper, der für den Boden gemacht scheint, und Blitze liefern einen weiteren Grund, den Schein zu überdenken." }, { "Manche Trolle verehren geflügelte Schlangen, und dunklere Beispiele haben ihren Platz unter Hakkars Anhängern. Die wilden Geschöpfe bleiben aus eigenem Recht eindrucksvoll. Vor einer kahlen Klippe kann eine Windnatter fast alle Farbe im Blick liefern." } } },
    ["wolves"] = { title = "Wölfe", note = { { "Ein Heulen kann einen ganzen Wald bewohnt erscheinen lassen. Wölfe leben von den Schneefeldern Dun Moroghs bis zu den Wäldern von Elwynn, und ihre verschiedenen Felle gehören so selbstverständlich an diese Orte wie die Bäume. Die größeren Worgs geben dem vertrauten Umriss einen schwereren Kiefer." }, { "Orcs haben Wölfe als Gefährten und Reittiere in ihr Leben geholt. Junge Jäger begegnen den wilden Rudeln auf ganz anderem Fuß. Hunger zeigt sich besonders deutlich an den verhungernden Wölfen nahe besiedelter Straßen. Der Abstand zwischen Wildnis und Dorf ist manchmal sehr kurz." } } },
    ["worgen"] = { title = "Worgen", note = { { "Arugal rief die Worgen in den Silberwald, um gegen die Geißel zu kämpfen, und verlor die Kontrolle über das, was er beschworen hatte. Burg Shadowfang ist nun ihre Festung, während das nahe Pyrewood unter einem Fluch steht, der seine Bewohner nach Einbruch der Nacht verwandelt." }, { "Die Nachtheuler des Dämmerwalds gehören zu einem anderen schwierigen Bericht, verstrickt mit der Sense von Elune und dem Ruf, den Velinde Starsong beschrieb. Ihre Gegenwart lässt sich nicht einfach erklären, indem man auf Arugals Turm zeigt." }, { "Beide Orte haben denselben schrecklichen Umriss zwischen den Bäumen angenommen: einen Wolfskopf über einem aufrechten Körper. Den Geschichten dahinter muss man getrennt nachgehen." } } },
    ["worms-and-grubs"] = { title = "Würmer und Maden", note = { { "Viel von der Arbeit der Welt geschieht unter ihrer Oberfläche. Maden bewegen sich durch die Fäulnis der Pestländer, während größere Wühler Sand und Stein bewohnen. Was wie leerer Boden aussieht, kann voller Leben sein." }, { "Die Felswürmer der Tiefe bringen das Thema einem Prospektor mit ungewöhnlicher Wucht nahe. Ein Geschöpf, das bequem ins Innere der Erde gehört, ist ein unbequemer Nachbar für jeden, der einen Tunnel hindurchgraben will. Der Fels war offenbar nicht unbewohnt." } } },
    ["yetis"] = { title = "Yetis", note = { { "Yetis bewohnen Berghöhlen von Alterac bis Winterspring, mit einer zottigen Art auch in den Höhen von Feralas. Ihre breiten Körper und schweren Pelze geben selbst einer großen Höhle das Aussehen einer engen Unterkunft." }, { "Ihre Hörner haben die Aufmerksamkeit von Umi Rumplesnicker in Everlook geweckt. Sie braucht ein vollkommenes Paar für den mechanischen Yeti, den sie baut, um ihre Freunde zu erschrecken. Die lebenden Yetis hängen unpraktischerweise an diesen Teilen." } } },
  },
  atlas = {
    [1411] = { { "Durotars rote Schluchten lenken die Straßen zwischen seinen Siedlungen. Der Klingenhügel steht dort, wo sie sich treffen, mit Orgrimmar im Norden, Sen'jin zur Südküste hin und dem Übergang ins Brachland im Westen." }, { "Das Tal der Prüfungen liegt abseits der Hauptstraße. Burg Tiragarde besetzt die Ostküste, während die Echoinseln vom Land der Dunkelspeer aus vor der Küste zu sehen sind, ohne sicher in den Händen der Dunkelspeer zu sein." }, { "Vor Orgrimmar geben die Zeppelintürme dem Zugang eine zweite Silhouette über den Schluchtwänden. Wer hier eine Überfahrt übers Meer sucht, sollte nach oben schauen." } },
    [1412] = { { "Grüne Ebenen und weidende Kodos unter einem weiten Himmel: die Heimat der Tauren. Thunder Bluff steht im Norden auf seinen Tafelbergen. Bloodhoof liegt im Süden, und die Straße verläuft zwischen beiden und nach Osten hinaus ins Brachland." }, { "Die Ebenen sind meist freundlich. Die Brunnen gehören den Tauren und sind es wert, bewacht zu werden. Die Gnolle des Bleichmähnenfelsens, die Harpyien des Windfurienkamms und die Mine der Venture Co. sind es nicht. Die Zwerge an der Grabungsstätte von Bael'dun graben dort, wo die Tauren es lieber nicht hätten." }, { "Die Teufelsfelsen im Osten sind eine Ruhestätte der geehrten Toten der Tauren. Geh leise dort." } },
    [1413] = { { "Crossroads gibt dem Brachland eine Mitte, von der aus sich die Straßen klar verteilen: nach Norden nach Ashenvale, nach Osten nach Ratchet, nach Westen ins Steinkrallengebirge und nach Süden durch Camp Taurajo zum großen Aufzug." }, { "Das offene Land macht ferne Orientierungspunkte leicht sichtbar und leicht unterschätzt. Dornenwälle markieren das Land der Stacheleber. Zentaurenlager und verstreute Oasen unterbrechen die Ebenen. Ein Ort, der am Horizont zu sehen ist, kann trotzdem einen langen Fußmarsch entfernt sein." }, { "Der Hafen von Ratchet verbindet die Ostküste mit Booty Bay. Im Landesinneren ist die Straße die verlässlichste Linie durch eine Landschaft, die in jede Richtung Raum bietet." } },
    [1416] = { { "Die Straße aus Hillsbrad steigt von grünen Vorbergen hinauf in den Schnee und zu den Überresten des Königreichs Alterac. Strahnbrad ist vom Syndikat besetzt, während Oger einen Großteil der zerstörten Hauptstadt halten. Ein Turm auf einem Grat ist ein nützlicher Orientierungspunkt, aber ein schlechtes Versprechen von Obdach." }, { client = "classic", "Am Lordameresee ist Dalarans violette Kuppel über dem tieferen Land zu sehen. Die Magier bauen dahinter wieder auf. Die Straße bringt einen Reisenden an die Außenseite ihrer Arbeit." }, { client = "forever", "Dalaran steht am Lordameresee, wo Erzmagierin Modera Hilfe bei einer Krise in der Stadt sucht. Gestörte Kraftlinien haben ihre Konstrukte zerstörerisch werden lassen. Die Stadt hat genug Wachen, um von der Straße aus geordnet zu wirken." }, { "Weiter oben unterbrechen Yetihöhlen und Schneefelder die Bergpfade. Der See gibt darunter einen festen Punkt. Zwischen den Graten ist die nächste Abzweigung oft verborgen." } },
    [1417] = { { "Der Thandol-Übergang trägt die Straße aus dem Sumpfland in ein Land aus grünen Hängen und alten Befestigungen. Der Thoradinswall markiert den westlichen Durchgang nach Hillsbrad. Die großen Mauern von Stromgarde erheben sich über der Südwestküste." }, { "Die Zuflucht liegt für die Allianz zwischen den mittleren Hügeln, während Hammerfall den Nordosten für die Horde hält. Stromgarde selbst ist zwischen überlebenden Verteidigern, Truppen des Syndikats und Ogern geteilt. Eine Mauer, die auf einer Karte unversehrt eingezeichnet ist, muss keine einzige sichere Siedlung umschließen." }, { "Die Bindungskreise sind auffällige Orientierungspunkte auf dem offenen Gelände. Die Faldirbucht liegt versteckt unter den südlichen Klippen, von der Straße aus weit weniger zu erkennen als vom Meer." } },
    [1418] = { { "Der Abstieg aus Loch Modan lässt das grüne Land abrupt hinter sich. Rote Grate zerteilen das Ödland in lange, trockene Täler, mit Kargaths Mauern im Westen und den Ausgrabungen um Uldaman nahe dem nördlichen Zugang." }, { "Die Festung Angor ist Boden der Dunkeleisenzwerge. Ogerlager besetzen die südlichen Hügel, und schwarze Drachkin halten die Lethlorklamm im Osten. Die übersichtlichste offene Strecke ist nicht unbedingt der ruhigste Weg." }, { "Die Grabungen der Liga bieten mehrere nützliche Orientierungspunkte, auch wenn ein Zelt und eine Abraumhalde vom nächsten Grat aus sehr ähnlich aussehen können. In diesem Land verrät die Farbe des Gesteins einem Vermesser weniger als seine Form." } },
    [1419] = { { "Die Straße von den Sümpfen des Elends nach Süden erreicht Burg Nethergarde über einer roten Öde. Die Festung bewacht das Dunkle Portal, dessen erhaltener Rahmen weiter südlich in dem Land steht, das die Invasion vernarbt hat." }, { "Die Schreckensfelsoger besetzen die westlichen Hügel, und Dämonen halten die Faulende Narbe. Jenseits der Burg hat ein Reisender nur wenige freundliche Orientierungspunkte. Das Portal ist leicht genug zu finden. Einen behaglichen Ort in seiner Nähe zu finden, ist eine andere Sache." } },
    [1420] = { { "Die Straßen von Tirisfal verbinden Deathknell, Brill und die Ruinen der Hauptstadt Lordaerons und führen dann nach Osten zum Bollwerk. Die alten Höfe und Mühlen geben dem Land noch erkennbare Grenzen, auch wenn viele ihrer Bewohner tot sind." }, { "Das Scharlachrote Kloster besetzt den Nordosten, mit Wachposten dahinter. Am Ufer des Blendwassersees leben Murlocs, und die Wälder verbergen ihre eigenen Gefahren." }, { "Brill ist die wichtigste Siedlung der Verlassenen an der Straße. Nahe den Ruinen der Hauptstadt verbinden Zeppelintürme dieses stille Land mit Orgrimmar und Grom'gol, ein unerwartet belebter Treffpunkt von Routen über den Bäumen." } },
    [1421] = { { "Der Silberwald erstreckt sich zwischen Tirisfal und der geschlossenen Grenze von Gilneas. Das Grabmal liegt über der Hauptstraße, die nach Süden an Pyrewood vorbeiführt und sich dann nach Hillsbrad wendet." }, { "Burg Shadowfang erhebt sich über Pyrewood, dessen vertraute Dorfstraßen bei Nacht zum Boden der Worgen werden. Weiter südlich versperrt der Graumähnenwall die Straße nach Gilneas. Er ist eine Grenze mit einem Königreich dahinter, kein Pass durch die Berge." }, { "Die Magier von Ambermill besetzen die östlichen Wälder. Zwischen ihren Besitzungen, der Burg und den Siedlungen der Verlassenen kommt eine kurze Durchquerung auf der Karte an mehreren sehr verschiedenen Ansprüchen auf den Wald vorbei." } },
    [1422] = { { "Die Straße kommt am Bollwerk herein und durchquert zerstörtes Ackerland bis zum Thondroril. Andorhal steht nahe der Mitte, und seine Straßen und zerfallenen Gebäude markieren noch die alte Getreidestadt." }, { "Hearthglen bleibt im Norden eine Festung des Scharlachroten Kreuzzugs. Im Süden liegt Caer Darrow auf einer Insel im Darrowmeresee, mit der Scholomance darunter. Das Chillwind-Lager gibt der Allianz in der Nähe einen Stützpunkt." }, { "Die Höfe sind leicht zu erkennen und schwer zu erreichen. Ihre Seuchenkessel haben jedes Feld zu einem eigenen Stück feindlichen Bodens gemacht, wo eine Straßenkarte einem ganz anderen Zweck dienen muss, als die Ernte einzubringen." } },
    [1423] = { { "Der Thondroril markiert den westlichen Zugang zu einem Land aus toten Bäumen und zerstörten Höfen. Die Straßen erreichen Stratholme im Nordwesten und die Kapelle des hoffnungsvollen Lichts im Osten, wo die Argentumdämmerung eine Zuflucht unterhält." }, { "Tyrs Hand ist eine Festung des Scharlachroten Kreuzzugs im Südosten. Zul'Mashar besetzt die nördlichen Höhen. Über dem Pestwald schwebt Naxxramas. Wenige Orientierungspunkte sind leichter zu erkennen oder unwillkommener anzusehen." }, { "Die Gebäude von Darrowshire markieren noch ein Dorf auf der Ebene, auch wenn seine Bewohner zu einem schwierigeren Bericht gehören. In diesem Land kann eine Karte vollkommen genau bleiben, nachdem fast alles, was sie beschreibt, verloren ist." } },
    [1424] = { { "Hillsbrad liegt zwischen den Hängen Alteracs und dem Meer. Southshore gibt der Allianz einen Hafen und eine Stadt an der Küste. Tarrens Mühle ist der Stützpunkt der Verlassenen im Landesinneren. Höfe und umkämpfte Straßen füllen den Raum dazwischen." }, { "Die östliche Route erreicht Arathi durch den Thoradinswall. Andere Wege führen nach Westen in den Silberwald, nach Norden nach Alterac und hinauf zum Hinterland. Die zerstörten Mauern von Durnholde fallen nahe den östlichen Straßen ins Auge, auch wenn das Syndikat nun die alte Internierungsburg hält." }, { "Dies müsste ein einfach zu durchquerendes Land sein: niedrige Hügel, bestellte Felder und reichlich Straßen. Die Schwierigkeit liegt selten im Gelände." } },
    [1425] = { { "Der westliche Zugang steigt aus Hillsbrad hinauf nach Aerie Peak, wo sich die Greifen der Wildhammer die Höhen über dem Tal teilen. Die Straße windet sich dann nach Osten durch bewaldete Hügel und alte Besitzungen der Trolle." }, { "Jintha'Alor erhebt sich im Südosten in Terrassen, während der große Baum von Seradane im Norden Land markiert, das Drachen halten. Revantusk liegt an der Ostküste und bietet der Horde unterhalb der Hügel einen eigenen Stützpunkt." }, { "Die Höhe von Aerie Peak bietet einen schönen ersten Ausblick, doch ein Großteil des Weges verschwindet unter Bäumen, bevor er das Meer erreicht. Die Wildhammer haben ein ausgezeichnetes Land für Reisen per Greif gewählt." } },
    [1426] = { { "Schnee, Stein und Zwerge, in dieser Reihenfolge. Die Täler verlaufen von Osten nach Westen unterhalb der Gipfel, die Ironforge verbergen, und die eine Straße folgt ihnen: vom Coldridgetal durch den Tunnel nach Kharanos, hinauf zum großen Tor der Stadt und weiter nach Osten durch den Pass nach Loch Modan." }, { "Kharanos hat die Brauerei Donnerbräu und das beste Feuer im Land. Westlich davon gehört der Boden den Trollen der Frostmane, und weiter westlich steht Gnomeregan hinter seinen Mauern, vergiftet. Die Gnome gehen nicht nach Hause, und du solltest nicht ohne guten Grund und bessere Freunde hineingehen." }, { "Nimm einen Ersatzumhang mit und bleib bei einem Schneesturm auf der Straße. Die Verwehungen sind tief, und den Troggs von Coldridge ist es gleich, dass du dich verlaufen hast." } },
    [1427] = { { "Der Kessel schneidet eine große Grube in die Mitte der Sengenden Schlucht, und die Anlagen der Dunkeleisenzwerge reichen unter die Oberfläche. Von oben zeigen die Gerüste und Mineneingänge nur einen Teil des Landes, das ein Reisender womöglich durchqueren muss." }, { "Die Thoriumspitze ist der Stützpunkt der Thoriumbruderschaft im Norden. Der Blackrock bietet den Durchgang nach Süden in die Brennende Steppe. Zugänge aus den Nachbarländern erreichen die Schlucht durch schmalere Lücken in den Bergen." }, { "Schlackehalden und zerbrochene Maschinen sind hier nützliche Orientierungspunkte. Es ist eine Landschaft, in der gearbeitet wird, so zerstört sie vom nächsten Grat aus auch aussieht." } },
    [1428] = { { "Der Blackrock beherrscht den nördlichen Horizont und gibt fast jedem Weg über die Steppe denselben großen Orientierungspunkt. Der Zugang aus dem Rotkammgebirge steigt in aschdunkles Land hinauf, wo zerbrochene Grate und alte Befestigungen die Ebene unterbrechen." }, { "Morgans Wacht besetzt die östlichen Höhen für die Allianz. Der Flammenkamm bietet der Horde weiter nördlich einen Stützpunkt. Zwischen ihnen liegen Lager der Blackrock, Drachkin und die Überreste älterer Schlachten." }, { "Der Berg ist auch der Durchgang zur Sengenden Schlucht. Von außen wirkt er wie eine massive Mauer am Ende des Landes. Im Inneren wird die Größe seiner Brücken und Kammern zum nächsten Problem des Reisenden." } },
    [1429] = { { "Die Hauptstraße von Elwynn führt von Stormwind durch Goldhain und nach Osten ins Rotkammgebirge. Nordhain liegt in einem geschützten Tal im Norden, während der westliche Übergang nach Westfall führt. Höfe, Brücken und Seen geben diesem Land ungewöhnlich klare Anhaltspunkte." }, { "Die Minen sind weniger ordentlich als die Felder über ihnen: Kobolde besetzen die Tiefenschachtmine und die Jaspismine, und die Defias treiben ihr Unwesen bis tief in den Wald. Im Südwesten machen die Lager der Flusspfoten das offene Waldland um den Fluss zu gefährlichem Boden." }, { "Stormwind ist nie viele Meilen entfernt. Ein Bauer, der auf Hilfe gegen eine Mine oder ein Lager wartet, misst die Entfernung vielleicht anders." } },
    [1430] = { { "Die Straße vom Dämmerwald zu den Sümpfen des Elends überquert den Gebirgspass der Totenwinde zwischen kahlem Fels und tiefen Abgründen. Der Hauptweg ist auf einer Karte kurz genug, doch die toten Bäume und leeren Gebäude geben wenig Anlass zu verweilen." }, { "Eine südliche Abzweigung führt hinab nach Karazhan und zu dem verlassenen Dorf darunter. Der Turm ist in diesen Tagen versiegelt. Seine Höhe macht ihn zu einem ausgezeichneten Orientierungspunkt über einem Land, in dem fast alles andere aufgehört zu haben scheint zu wachsen." } },
    [1431] = { { "Die Straßen des Dämmerwalds führen durch einen Wald, der dem Boden wenig Tageslicht lässt. Dunkelhain ist die wichtigste Zuflucht im Osten, und die Nachtwache hält seine Zugänge. Dahinter liegt der Gebirgspass der Totenwinde. Die südliche Straße führt hinab ins Schlingendorntal." }, { "Im Westen liegen Rabenflucht und sein Friedhof in einem Land, das weit weniger sicher ist, als die vertrauten Hofnamen auf der Karte vermuten lassen. Der verlassene Obstgarten und die leeren Häuser bewahren die Gestalt eines besiedelten Tals, ohne viel von seinem alten Leben." }, { "Die Straßen verbinden noch immer die Orte, denen sie dienen sollten. Das macht sie zu nützlichen Anhaltspunkten, selbst wenn das Ziel zu einem Ort geworden ist, an dem ein Reisender lieber vorbeigeht." } },
    [1432] = { { "Ein langer See, aufgestaut vom Stonewroughtdamm, dem schönsten Stück zwergischer Ingenieurskunst außerhalb von Ironforge, und ich dulde keinen Widerspruch. Thelsamar liegt am Westufer an der Straße aus Dun Morogh, und die Straße führt weiter nach Norden ins Sumpfland und nach Süden ins Ödland." }, { "Über das Tal der Könige am Pass wachen steinerne Könige. Der Rest des Landes muss bewacht werden: Troggs im Splittersteintal, Kobolde in den Minen und Oger in der Festung Mo'grosh in den nordöstlichen Hügeln." }, { "Die Hochelfen der Weitschreiter-Lodge bleiben unter sich und kennen das Land besser als jeder Zwerg. Frag sie, bevor du auf die Jagd gehst." } },
    [1433] = { { "Seenhain liegt am Westufer des Immerruhsees, wo Brücken und Straßen die Zugänge aus Elwynn und dem Dämmerwald verbinden. Das Wasser gibt dem Tal eine weite, schöne Mitte und ungewöhnlich klare Anhaltspunkte." }, { "Die östlichen Höhen sind eine andere Sache. Burg Steinwacht ist in der Hand der Blackrock, und Gnolllager besetzen die Grate zwischen besiedeltem Boden und den Bergen." }, { "Von Seenhain aus wirkt das ferne Ufer nah genug, um zum eigenen Land der Stadt zu gehören. Die Wachen sehen es weit weniger friedlich." } },
    [1434] = { { "Das Schlingendorntal erstreckt sich vom südlichen Rand des Dämmerwalds bis Booty Bay durch einen langen Streifen Dschungel. Die Straße führt an den nördlichen Expeditionen und an Grom'gol, dem Lager der Horde, vorbei, bevor sie den Goblinhafen am anderen Ende erreicht." }, { "Ruinen und besetzte Lager liegen dicht hinter den Bäumen: Kurzens Truppenlager, Trollsiedlungen, der Boden der Mosh'Ogg und die Zugänge nach Zul'Gurub. Eine Lichtung bietet eine Aussicht, ohne unbedingt einen sicheren Rastplatz zu bieten." }, { "Booty Bay ist am steilen Fels rund um seinen Hafen gebaut, und das Schiff nach Ratchet wartet unter den Stufen der Stadt. Nach so viel Dschungel ist eine Route, die über offenes Wasser gemessen wird, eine willkommene Abwechslung." } },
    [1435] = { { "Die westliche Straße kommt vom Gebirgspass der Totenwinde herein und durchquert den Sumpf nach Stonard, der wichtigsten Siedlung der Horde. Eine südliche Abzweigung erreicht die Verwüsteten Lande. Abseits der Straße unterbricht seichtes Wasser immer wieder, was nach festem Boden aussieht." }, { "Der Tränenteich bedeckt den Tempel von Atal'Hakkar. Das Fallow Heiligtum liegt weiter östlich, während der sichere Hafen im Norden Flüchtlingen der Draenei Schutz bietet. Wer die Küste erreichen will, muss weit über das letzte verlässliche Stück Straße hinaus." }, { "Der Sumpf bietet wenig Höhe, von der aus man sich orientieren könnte. Ein Tempel, der unter einem See versunken ist, ist ein besonders wenig hilfreicher Orientierungspunkt für jemanden, der den See sucht." } },
    [1436] = { { "Die Straße von Westfall führt aus Elwynn in offenes Ackerland und weiter zur Späherkuppe. Die Volksmiliz hält den Turm, der ein nützlicher Orientierungspunkt über Feldern bleibt, deren Besitzer oft geflohen sind." }, { "Moonbrook liegt weiter südlich, mit den Todesminen darunter. Anderswo besetzen Lager der Defias und feindselige Erntegolems ein Land, das noch immer von Hecken und Feldwegen geteilt wird." }, { "Der Leuchtturm ist von der Westküste aus ein klarer Anhaltspunkt, auch wenn Murloclager den Zugang unterbrechen. Es gibt reichlich Raum, um über Westfall hinwegzusehen. Zu wissen, was auf dem nächsten Feld wartet, ist der schwierigere Teil." } },
    [1437] = { { "Dun Algaz führt die Straße aus Loch Modan hinab in weite Moore, wo sich die Hauptwege trennen, zum Hafen von Menethil im Westen und zum Thandol-Übergang im Norden. Die erhöhte Straße gibt eine festere Linie durch ein Land, das von seichtem Wasser geteilt wird." }, { "Die Schiffe von Menethil verbinden das Sumpfland mit Auberdine und Theramore. Im Landesinneren besetzen Lager der Dragonmaw die Hügel, Dunkeleisenzwerge halten Dun Modr, und rote Drachkin bewachen im Osten die Zugänge nach Grim Batol." }, { client = "forever", "Jenseits der älteren Grabung an Whelgars Ausgrabungsstätte reicht die neue Ausgrabung in uralte Anlagen hinein. Relikte, die zu Whelgar zurückgebracht werden, geben der Liga guten Grund, den Zugang auf ihren Karten zu behalten." }, { "Abseits der Straße kann Schilf den Rand eines Kanals ebenso leicht verbergen wie einen Krokilisken. Der kürzeste Weg zur nächsten Anhöhe kann weit mehr Wasser enthalten, als die Karte vermuten lässt." } },
    [1438] = { { "Teldrassil trägt einen ganzen bewohnten Wald über dem Meer. Die Straße führt von Shadowglen durch Dolanaar nach Darnassus, mit Abzweigungen in Lichtungen und Hügelgräberland, das sich weit vom Rand einer Insel entfernt anfühlen kann." }, { "Das Revier der Waldweber und die Besitzungen der Knarzklauen unterbrechen die besiedelten Wälder. Teiche bieten häufige Orientierungspunkte, auch wenn ihre umschlossenen Ufer wenig von der Höhe unter ihnen verraten." }, { "Der Weg hinab führt durch das Portal von Darnassus nach Rut'theran, wo die Boote von den Wurzeln ablegen. Es lohnt sich, diesen Weg im Kopf zu behalten: Eine Küste nützt einem Reisenden wenig, wenn sie so weit unter der Straße liegt." } },
    [1439] = { { "Die Dunkelküste ist eine lange Reise entlang einer schmalen Küste. Auberdine sammelt in der Mitte die Straßen und die Schifffahrt, mit Booten hinüber nach Rut'theran und über das Meer zum Hafen von Menethil. Die südliche Straße führt nach Ashenvale." }, { "Der Strand und die Wälder im Landesinneren bieten sehr verschiedene Reisewege. Wracks und Murloclager unterbrechen die Strände. Im Landesinneren liegen die Spukruinen von Ameth'Aran und Bashal'Aran, die Lager der Schwarzfelle und der Turm von Althalaxx." }, { "Das Meer ist ein verlässlicher Führer, wenn die Bäume die Straße verbergen. Es ist auch der Grund, warum so viele zerbrochene Schiffe zu Orientierungspunkten geworden sind." } },
    [1440] = { { "Ashenvales Hauptstraße führt durch tiefen Wald nach Astranaar und dann nach Osten zu den Lagern der Warsong und nach Azshara. Abzweigungen führen nach Norden an die Dunkelküste, nach Westen durch den Gebirgsdurchgang ins Steinkrallengebirge und nach Süden zum Wall von Mor'shan." }, { "Die Siedlungen liegen weit genug auseinander, dass sich der Wald zwischen ihnen um einen Reisenden schließt. An der Küste öffnet sich der Zoramstrand zu Ruinen, die die Naga halten. Im Landesinneren machen Furbolglager und der dämonische Boden um Felfire Hill mehrere einladende Lichtungen zu schlechten Rastplätzen." }, { "Die Brücken und der See von Astranaar bieten einen willkommenen festen Punkt inmitten von so viel Holz. Dahinter reicht der Blick selten weit genug, um den ganzen Weg voraus zu zeigen." } },
    [1441] = { { "Der große Aufzug führt aus dem Brachland hinab in eine Schlucht voller Steinsäulen. Der Freiwindposten steht oben auf einer davon und ist über eigene Aufzüge zu erreichen. Unten fädelt sich die Straße zwischen Klippen hindurch zur Schimmernden Ebene." }, { "Der Düsterwolkengipfel ist Boden der Grimmtotem, während Zentauren und Harpyien andere Seitenschluchten besetzen. Die Säulen sind gute Orientierungspunkte, bis die nächste sie verdeckt." }, { "Nach Osten öffnet sich das Land plötzlich zu Salzebenen und zur Illusionenrennbahn. Maschinen von Gnomen und Goblins füllen ein Land, das endlich weit genug ist, damit ein Reisender weit sehen kann, ohne nach oben zu schauen." } },
    [1442] = { { "Die Straßen des Steinkrallengebirges steigen durch enge Täler hinauf, mit Sonnenfels in der Mitte des Gebirges und Malaka'jin nahe den südlichen Zugängen. Die Nachtelfen halten den Steinkrallengipfel weit im Norden." }, { "Die Rodungen der Venture Co. haben große Wunden in den Wald geschlagen. Weiter westlich ist das verkohlte Tal verbrannter Boden, auf dem Harpyien und andere Gefahren hausen. Der Weberpass trägt eine noch wörtlichere Warnung im Namen." }, { "Der Gebirgsdurchgang nach Ashenvale und die Straßen hinab ins Brachland und nach Desolace machen dies zu einem Ort der Übergänge. Die Entfernung allein ist ein schlechtes Maß für eine Reise durch so viele Windungen und Anstiege." } },
    [1443] = { { "Desolace öffnet sich unterhalb des Steinkrallengebirges in grauen Graten und weitem, ungeschütztem Gelände. Die Nijelspitze besetzt die nördlichen Höhen für die Allianz. Shadowprey liegt unten an der Westküste für die Horde. Die südliche Route erreicht Feralas." }, { "Gebiete der Zentauren füllen einen Großteil des Landesinneren, mit dem Kodofriedhof mitten unter ihnen. Die Festung Thunder Axe und Mannorocs Koven markieren feindlichen Boden anderer Art. An der Küste fällt das Land zu Gewässern ab, die die Naga halten." }, { "Die Knochen machen den Friedhof schon von weitem auffällig. Das Ufer von Shadowprey bietet dem Auge etwas Sanfteres zum Ausruhen: eine Siedlung, die zum Meer hin gebaut ist, statt eines weiteren Lagers im Staub." } },
    [1444] = { { "Feralas schließt sich mit gewaltigen Stämmen und dichtem Unterholz um die Straße. Der nördliche Durchgang kommt aus Desolace herab. Nach Osten erreicht die Route Camp Mojache und führt weiter nach Tausend Nadeln." }, { "Die Festung Feathermoon steht vor der Küste auf der Insel Sardor, mit dem Boot von der Westküste aus erreichbar. Im Landesinneren erhebt sich Düsterbruch über den Wald, und Oger besetzen einen Großteil der zerstörten Stadt. Der große Baum von Traum-Geäst markiert weiter nördlich Boden, den Drachen halten." }, { "Das Blätterdach kann einen beträchtlichen Hang verbergen, bis die Straße ihn hinaufzusteigen beginnt. Eine Vermessung von Feralas braucht Platz für die Höhe ebenso wie für die Entfernung." } },
    [1445] = { { "Die Straße aus dem Brachland führt durch Schilf und seichtes Wasser in die Marschen von Dustwallow und erreicht schließlich Theramores Damm und Hafen. Schiffe nach Menethil legen von der Inselstadt ab. Brackenwall, eine Siedlung der Horde, zu deren Bewohnern auch Oger der Stonemaul gehören, steht in der nordwestlichen Marsch." }, { "Onyxias Land liegt im Süden im Drachensumpf. Anderswo zerteilen Kanäle und niedrige Ufer einen Boden, der aus der Ferne zusammenhängend aussieht. Eine Biegung der Straße ist oft ein sichererer Anhaltspunkt als die Bäume, die einander unglücklich ähnlich sehen." }, { "Vom Mauerwerk Theramores aus wirkt das Festland sehr nah. Nach ein paar Windungen durch die Marsch kann die Stadt dahinter wie verschwunden scheinen." } },
    [1446] = { { "Der Abstieg aus Tausend Nadeln erreicht Gadgetzan nahe dem nördlichen Ende von Tanaris. Seine Mauern und Steamwheedle an der Ostküste sind nützliche feste Punkte in einer Wüste, deren südliche Weiten weit weniger besiedelt sind." }, { "Zul'Farrak steht im Nordwesten, die Oger der Dünenbrecher besetzen das Landesinnere, und die Lost-Rigger-Bucht bietet Piraten hinter den östlichen Hügeln Schutz. Die Höhlen der Zeit öffnen sich weiter südöstlich in den Bergen." }, { "Die Route nach Westen führt schließlich hinab nach Un'Goro. Vom Kraterrand aus sieht der grüne Krater wie ein ganz anderes Land aus, was nach so viel Sand eine ungewöhnlich angenehme Entdeckung ist." } },
    [1447] = { { "Die Straße kommt aus Ashenvale über einer Küste aus zerbrochenen Tempeln und rotgoldenen Bäumen herein. Die Talrendisspitze und Valormok bieten kleine Stützpunkte nahe dem westlichen Zugang. Weiter östlich fallen die Hügel steil zur Bucht der Stürme ab." }, { "Naga besetzen einen Großteil der Küste, während Satyrlager und elfische Expeditionen Boden zwischen den Ruinen halten. Azuregos streift durch den Süden. Eine gerade Linie auf der Karte kann sowohl eine Klippe als auch den langen Umweg um sie herum verbergen." }, { client = "classic", "Das große Tor in den nördlichen Hügeln ist als Holzschlundfeste verzeichnet, doch es ist verschlossen. Die begangenen Tunnel der Furbolgs nach Moonglade und Winterspring liegen im Teufelswald, weit westlich von hier." }, { client = "forever", "Das große steinerne Tor in den nördlichen Hügeln führt zur Schwarzschlundfeste, der Heimat eines verderbten Furbolgstammes. Die Tunnel der Holzschlundfeste nach Moonglade und Winterspring liegen weiterhin weit westlich von hier, im Teufelswald." } },
    [1448] = { { "Die Straße des Teufelswalds führt von Ashenvale nach Norden durch einen Wald, dessen tote und kranke Bäume lange Lücken im Blätterdach lassen. Das Smaragdrefugium liegt nahe dem südlichen Zugang. Der Blutgiftposten und die Nachtlaublichtung bieten weiter das Tal entlang getrennte Stützpunkte." }, { "Jaedenar und die Lager der Jadefeuersatyrn besetzen einige der am tiefsten verderbten Böden. Am nördlichen Ende führen die Tunnel der Holzschlundfeste nach Moonglade und Winterspring, sofern ihre Wachen den Durchgang erlauben." }, { "Ein grüner Teich spendet einer durstig wirkenden Landschaft hier keinen Trost. Die Farbe gehört zum Schaden und schimmert oft schon durch die Bäume, bevor der Teich selbst zu sehen ist." } },
    [1449] = { { "Der Pfad hinab aus Tanaris enthüllt Un'Goro auf einen Schlag: dichter Dschungel um den Feuerfedergrat, mit Teergruben und heißen Quellen, die das Grün unterbrechen. Marshals Zuflucht liegt am nördlichen Rand. Der Weg hinaus nach Silithus steigt im Nordwesten an." }, { "Der Vulkan in der Mitte ist ein ausgezeichneter Anhaltspunkt und schwieriges Gelände. Abseits davon verbirgt das Blätterdach Raptoren, Teufelssaurier und das Gebiet der Silithiden in der wuchernden Narbe. Der Krater lässt sich von oben leichter überblicken als unten durchqueren." }, { client = "classic", "Leuchtende Kristalle finden sich überall im Becken, und die Pylonen bieten der Expedition einen weiteren Gegenstand für ihre Untersuchungen. Die Karte verzeichnet ihre Lage. Sie zu erklären ist eine andere Arbeit." }, { client = "forever", "Die Shapers' Terrace gibt den Spuren der Titanen im Krater einen Platz auf der Karte, neben den Pylonen und verstreuten Kristallen. Ein Name für eine uralte Stätte lässt sehr viel Dschungel unerklärt." } },
    [1450] = { { "Der Elune'ara See liegt in der Mitte von Moonglade, mit Nighthaven an seinem Ufer und dem Schrein von Bewahrer Remulos in der Nähe. Druiden kommen durch ihre eigene Magie. Andere Reisende erreichen das Tal gewöhnlich durch die Tunnel der Holzschlundfeste aus dem Teufelswald." }, { "Der Zirkel des Cenarius heißt hier beide Fraktionen willkommen, und das Mondfest bringt Besucher von viel weiter her. Die Stille ist echt, auch wenn der Kampf um den Smaragdgrünen Traum selbst dieses Tal erreicht hat." }, { "Für einen Vermesser ist der See die willkommene Konstante: ein breiter, offener Anhaltspunkt nach dem engen Gebirgsdurchgang." } },
    [1451] = { { "Der Pfad aus Un'Goro erreicht Silithus am nordöstlichen Rand einer weiten Wüste. Burg Cenarius erhebt sich über dem Landesinneren und gibt Reisenden einen befestigten Punkt, von dem aus sie die Entfernungen zwischen den Stöcken einschätzen können." }, { "Der Twilight-Hammer besetzt Lager überall in der Öde, während der große Skarabäuswall im Süden Ahn'Qiraj markiert. Hügel der Silithiden unterbrechen, was sonst wie offener Sand aussehen kann." }, { "Der Südwindposten bleibt auf der Karte eine erkennbare Siedlung und am Boden eine Ruine. Die Straßen und Türme sind so spärlich, dass ein einziges stehendes Gebäude für die Orientierung sehr viel bedeuten kann." } },
    [1452] = { { "Der Durchgang der Holzschlundfeste öffnet sich zu den weiten Schneefeldern von Winterspring, wo Everlook nahe der Mitte den Handel sammelt. Die Stadt der Goblins gibt beiden Fraktionen ein Dach und einen Treffpunkt der Routen zwischen den Bergen." }, { "Starfall liegt im Westen, die blauen Drachkin von Mazthoril halten die Höhlen im Süden, und das Land der Yetis erhebt sich jenseits der Eisdistelberge. Lager der Winterfelle unterbrechen andere Zugänge durch den Schnee." }, { "Die flüsternde Schlucht schneidet sich in den fernen Süden, wo Dämonen eine trostlose Grenze des Tals bilden. Die heißen Quellen sind freundlichere Orientierungspunkte: dunkles offenes Wasser und aufsteigender Dampf vor sehr viel Weiß." } },
    [1453] = { { "Das Tor von Stormwind führt die Straße aus Elwynn an den Statuen im Tal der Helden vorbei in den Handelsdistrikt. Kanäle teilen die Viertel, und Brücken leisten einen Großteil der Arbeit, die in einer anderen Stadt eine breite Allee leisten würde." }, { "Greifen starten im Handelsdistrikt, und die Tiefenbahn verbindet den Zwergendistrikt mit Ironforge. Die Kathedrale ist ein leichter Orientierungspunkt über den Dächern. Das Verlies am Wasser ist ein weniger beruhigender." }, { "Der weiße Stein der Stadt ist noch immer eine eindrucksvolle Antwort auf ihre frühere Zerstörung. Um sie zügig zu durchqueren, braucht es etwas mehr Aufmerksamkeit für die Brücken als für die Silhouette." } },
    [1454] = { { "Orgrimmar folgt den Falten einer Schlucht aus rotem Fels, und sein Haupttor öffnet sich nach Süden nach Durotar. Rampen und Durchgänge verbinden die Täler im Inneren. Zwei Ziele, die auf einer flachen Karte nah beieinanderliegen, können einen langen Aufstieg dazwischen verlangen." }, { "Die Feste Grommash steht im Tal der Weisheit, während die Windreiter der Stadt von einem hohen Turm aus starten. Vor den Mauern verbinden Zeppeline die Hauptstadt mit Undercity und Grom'gol." }, { "Die Schlucht gehört ebenso zur Festung wie die gebauten Mauern. Ihre Form versteht man am leichtesten von oben, was bequem ist, sobald ein Reisender die Windreiter gefunden hat." } },
    [1455] = { { "Das Tor von Ironforge öffnet sich aus dem Schnee in eine Stadt, die um die Große Schmiede angelegt ist. Der Hauptring verbindet die Märkte, den Hohen Sitz, Tüftlerstadt und die Halle der Forscher. Wer weiß, in welche Richtung er um ihn herumgehen muss, spart sich einen guten Fußmarsch." }, { "Die Tiefenbahn fährt von Tüftlerstadt nach Stormwind, und Greifen starten neben der Großen Schmiede. Die Halle der Liga bietet ein ruhigeres Ziel, auch wenn die Ausstellungsstücke gelegentlich ebenso viel Streit auslösen wie das Auktionshaus." }, { client = "forever", "Unter der Stadt führen die Höhlen unter Alt-Ironforge zur Halle der Thanen. Eindringlinge der Dunkeleisenzwerge haben einen Weg in ihre unteren Gewölbe gefunden. Die Stadt hat eine weitere Grenze direkt unter den Füßen des Königs bekommen." } },
    [1456] = { { "Die Stadt der Tauren auf den Tafelbergen im Norden von Mulgore, verbunden durch Seilbrücken und von der Ebene unten über große Aufzüge zu erreichen." }, { "Jede Anhöhe hat ihren Zweck: die Anhöhe der Ältesten für die Ältesten und die Druiden, die Anhöhe der Geister für die Schamanen und die Priester, die Anhöhe der Jäger für die Jäger und die Krieger. Die Bank und das Auktionshaus liegen auf der mittleren Anhöhe, und die Windreiter fliegen vom Turm ab." }, { "Die Brücken schwanken. Schau nicht nach unten, und renn nicht." } },
    [1457] = { { "Darnassus öffnet sich um Wasser und breite Brücken hoch oben in Teldrassil. Der Tempel des Mondes gibt dem südlichen Teil der Stadt sein großes Wahrzeichen, während Händler und Handwerker die Terrassen weiter nördlich bewohnen." }, { "Die Straße nach Osten führt nach Dolanaar. An der Westseite der Stadt bietet das Portal den Weg hinab nach Rut'theran und zu den Booten darunter. Ein Vermesser, der gewohnt ist, die Höhe einer Stadt vom Boden aus zu messen, muss sich hier einiges umgewöhnen." } },
    [1458] = { { "Undercity liegt unter der zerstörten Hauptstadt Lordaerons und ist über Aufzüge unter dem alten Thronsaal oder durch den äußeren Zugang durch die Kanalisation zu erreichen. Im Inneren verbinden kreisförmige Gänge und grüne Kanäle die Viertel." }, { "Die Bank in der Mitte ist ein nützlicher Anhaltspunkt. Das Königsviertel und die Arbeit der Apotheker liegen tiefer in der Stadt. Um dorthin zu gelangen, muss man auf die Ebenen ebenso achten wie auf die Abzweigungen." }, { "Über der Erde stehen die Zeppelintürme vor den Ruinen. Ein Reisender, der auf dem Luftweg ankommt, hat womöglich nur einen sehr kurzen Weg zur Stadt und braucht trotzdem eine Weile, um den richtigen Weg hinab zu finden." } },
    [2521] = { { "Zephras ist eine bewohnte Insel, die im Himmelswall schwebt. Valanaar besetzt den südöstlichen Rand, mit dem Sitz des Hohen Ältesten und den Himmelsdocks. Ban'aethal im Norden wurde geräumt, da die Pylonen, die die Insel tragen, versagen." }, { "Die südlichen Höfe gehen in das Shen'darhochland über, dann in Dörfer, Schreine und den Schattenwindwald. Auf gewöhnlichem Boden ist eine zerstörte Straße eine Unannehmlichkeit. Hier ist der Boden selbst Teil der Ungewissheit der Vermessung geworden." }, { "Himmelsschiffe legen von Valanaar nach Dalaran und Mulgore ab. Die Routen nach Anvilas und Siroccas sind verstummt und lassen diese anderen Inseln jenseits der gegenwärtigen Anhaltspunkte des Reisenden." } },
  },
  herbs = {
    [13463] = { { "Traumblatt wird zwischen den Ruinen von Azshara und in Düsterbruch gesammelt, ebenso in den vernarbten Landen um den Blackrock." }, { "Große Schutztränke verwenden es gegen Feuer, Frost, Natur, Schatten und Arkanes. Auch das Fläschchen mit destillierter Weisheit braucht es." } },
    [13464] = { { "Goldener Sansam wird in Un'Goro und Azshara gesammelt und in so beschädigtem Land wie dem Teufelswald und den Östlichen Pestländern." }, { "Erhebliche Heil- und Verjüngungstränke verwenden ihn. Den Heilmitteln, die von diesen Orten zurückgebracht werden, fehlt es nicht an Arbeit." } },
    [13465] = { { "Bergsilberweisling wird in Winterspring und Un'Goro gesammelt, trotz der sehr verschiedenen Aussicht vom Kraterboden." }, { "Er kommt in erhebliche Heiltränke, und mit Pestblüte ergibt er das Elixier des Mungos." } },
    [13466] = { { "Pestblüte wird in den beiden Pestländern gesammelt, wo es eine kleine Erleichterung ist, zwischen den zerstörten Feldern nützliches Wachstum zu finden." }, { "Läuterungstränke und Magierbluttränke verwenden sie beide. Bergsilberweisling begleitet sie im Elixier des Mungos. Etwas, das in diesem verseuchten Land gesammelt wird, kann noch immer den Lebenden dienen." } },
    [13467] = { { "Eiskappe gehört zu den Sammelrouten von Winterspring. Der Schnee gibt einem Kräuterkundigen eine ungewöhnlich gleichförmige Landschaft, in der er ihren Platz lernen kann." }, { "Erhebliche Manatränke und Läuterungstränke verwenden sie, ebenso das Fläschchen mit destillierter Weisheit." } },
    [13468] = { { "Schwarzer Lotus ist ein seltener Fund in einer kleinen Zahl gefährlicher Länder. Ein Sammler, der ihn entdeckt, hat guten Grund, sich den Ort zu merken." }, { "Die großen Fläschchen verlangen danach, darunter das der Titanen und das mit oberster Macht. Viele Bündel lassen sich auf einer gewöhnlichen Runde wieder auffüllen. Dieses bestimmt meist, wann die ehrgeizigste Arbeit beginnen kann." } },
    [2447] = { { "Die Friedensblume ist eine vertraute Blume an den ersten Straßen, die von zu Hause fortführen, und nützlich noch lange, nachdem ein Kräuterkundiger seltenere Namen gelernt hat." }, { "Zusammen mit Silberblatt wird daraus ein Schwacher Heiltrank. Es hat etwas Angenehmes, die Anfänge eines Heilmittels in einem Land zu finden, in dem ein Lehrling noch den Weg zurück erkennt." } },
    [2449] = { { "Erdwurzel wächst überall in den besiedelten Landen und sogar in den Höhlen des Wehklagens. Sie ist eine der ersten Wurzeln, die ein Kräuterkundiger zu erkennen lernt." }, { "Das Elixier der Löwenstärke und das Elixier der schwachen Seelenstärke beginnen beide mit ihr. So eindrucksvolle Namen haben bescheidene Zutaten, was einen Lehrling tröstet." } },
    [2450] = { { "Die Wilddornrose ist im Brachland und in den bewaldeten Ländern jenseits des Meeres vertraut. Mit den gesammelten Stielen kann Flitzdistel mitkommen." }, { "Heiltränke und Wuttränke verlangen beide danach. Dasselbe Bündel kann also jemandem helfen, sich von einem Kampf zu erholen oder sich auf den nächsten vorzubereiten." } },
    [2452] = { { "Flitzdistel kommt mit Maguskönigskraut und Wilddornrose statt aus einem eigenen Vorkommen. Ein Kräuterkundiger, der sie sucht, muss darauf achten, was die andere Ernte hergibt." }, { "Schurken brauen daraus Disteltee, während Alchemisten sie für Tränke der Schnelligkeit und des Schwimmens verwenden." } },
    [2453] = { { "Beulengras ist weit genug verbreitet, um ein fester Teil der Sammelrunde zu werden. Die Höhlen des Wehklagens und die Blackfathom-Tiefe haben es ebenfalls, für alle, deren Aufträge unter die Erde führen." }, { "Heiltränke und das Elixier des Giftwiderstands geben ihm verlässliche Arbeit." } },
    [3355] = { { "Wildstahlblume ist ein vertrauter Name für Kräuterkundige, die die Hügel von Arathi und das felsige Land des Steinkrallengebirges absuchen." }, { "Das Elixier der Verteidigung und das Elixier der Seelenstärke verwenden sie beide. Rüstung ist Sache des Schmieds, doch der Alchemist hat ein paar Beiträge zu leisten, bevor der Reisende sie anlegt." } },
    [3356] = { { "Königsblut kommt in einem weiten Landstrich vor, von bewaldeten Hügeln bis zum trockenen Inneren Kalimdors. Sein Wert hängt nicht von einer schwierigen Suche ab." }, { "Große Heiltränke und Manatränke verwenden es beide, und Lederer brauchen es für Kräuterkundigenhandschuhe. Ein Sammelkraut, das Sammelhandschuhe herstellen hilft, hat einen erfreulichen Platz im Handwerk." } },
    [3357] = { { "Lebenswurz findet sich in feuchten Ländern auf beiden Kontinenten, und die Marschen und Flusslande bieten einen Großteil der Ernte." }, { "Große Heiltränke und das Elixier des Wasserwandelns verlangen danach." } },
    [3358] = { { "Khadgars Schnurrbart hat einen Namen, den sich ein Reisender wohl merkt, noch bevor er lernt, wo er danach suchen muss. Das Kraut kommt in mehreren der bewaldeten und sumpfigen Länder vor." }, { "Große Manatränke und das Elixier der großen Intelligenz verwenden ihn, ebenso Frostöl. Der Name des Erzmagiers hat seinen Weg auf ein sehr volles Regal gefunden." } },
    [3369] = { { "Grabmoos wird an Orten gesammelt, an denen sich ein Kräuterkundiger kaum ganz allein fühlen dürfte, darunter der Dämmerwald, Desolace und der Begräbnisgrund der Hügel von Razorfen." }, { "Schattenöl und Schattenschutztränke verlangen danach. Die Verwendungen passen gut zu den Aufträgen, die einen Sammler zwischen die Gräber führen." } },
    [3818] = { { "Blassblatt wird in den mittleren Landen gesammelt, mit Vorkommen auch im Scharlachroten Kloster und im Kral von Razorfen." }, { "Schurken bereiten daraus Blendungspulver. Alchemisten geben es in Tränke, mit denen man unsichtbar wird oder Unsichtbares entdeckt: Dasselbe Kraut trägt zu beiden Seiten einer schwierigen Begegnung bei." } },
    [3819] = { { "Winterbiss verschafft einem Kräuterkundigen eine besondere Reise: in den Schnee des Alteracgebirges. Eine vertraute Pflanze ist willkommene Gesellschaft in einem Land, in dem man die Pfade leicht verliert." }, { "Frostöl, Frostschutztränke und das Elixier der Frostmacht verlangen alle danach. Das Bergkraut hat Arbeit auf beiden Seiten des Kampfes gegen die Kälte." } },
    [3820] = { { "Würgetang führt den Kräuterkundigen vom Pfad weg und ins Küstenwasser. Schon das Sammeln ist ein gutes Argument dafür, zu wissen, was unter der Oberfläche wächst." }, { "Ein Elixier der Wasseratmung gehört zu seinen Verwendungen, neben Manatränken und Tränken der freien Aktion. Die Pflanze liefert ein Mittel gegen eine Unannehmlichkeit, der man beim Sammeln begegnet." } },
    [3821] = { { "Golddorn verdient sich durch die Vielfalt seiner Verwendungen einen Platz im Arbeitsbeutel. Zu seinem Sammelland gehören die Hügel von Arathi und die Wälder von Feralas." }, { "Große Manatränke, Elixiere der Beweglichkeit und Frostschutztränke verlangen alle danach." } },
    [4625] = { { "Feuerblüte gehört zu den Sammelrouten durch Tanaris, das Ödland und die Sengende Schlucht. Keines davon ist ein sanftes Land, um anzuhalten und einen Beutel zu füllen." }, { "Goblin-Raketentreibstoff und Öl des Feuerbrandes geben einen guten Eindruck von ihren Verwendungen. Auch der Stein der Weisen verlangt danach, für Alchemisten mit einem anderen Ehrgeiz für dasselbe Bündel." } },
    [765] = { { "Silberblatt gehört in denselben frühen Sammelbeutel wie die Friedensblume. Eine Pflanze muss nicht selten sein, um an der Werkbank unentbehrlich zu werden." }, { "Schwache Heil- und Manatränke verlangen beide danach. Diese beiden Verwendungen erklären, warum ein Alchemist, der reichlich gesammelt hat, schon recht bald feststellen kann, dass reichlich nicht genug war." } },
    [785] = { { "Maguskönigskraut ist ein nützlicher Fund an den Straßen jenseits der ersten Siedlungen. Manchmal sammelt man Flitzdistel mit ihm, was einem einzigen Halt eine zweite Belohnung beschert." }, { "Alchemisten verwenden Maguskönigskraut in Manatränken und im Elixier der Weisheit. Der Name weckt hohe Erwartungen. Was es für einen jungen Zauberwirker leistet, genügt vollauf." } },
    [8153] = { { "Wildranke wird zusammen mit Lila Lotus gesammelt, ein zusätzlicher Fund in einem Land, das die Suche nach der Blume ohnehin lohnt." }, { "Lederer brauchen sie für Wildleder und Schneider für Traumzwirn. Die Blume und ihre Begleiterin finden Arbeit an ganz verschiedenen Werkbänken." } },
    [8831] = { { "Lila Lotus wächst in verstreuten Ländern auf beiden Kontinenten und bringt beim Sammeln manchmal Wildranke mit." }, { "Tränke des traumlosen Schlafs und das Elixier der Traumvision verwenden ihn beide. Ein Alchemist kann eine Nacht ohne Träume oder eine Reise durch einen Traum anbieten, je nachdem, was den Lotus in der Phiole begleitet." } },
    [8836] = { { "Arthas' Tränen wachsen in den Pestländern und im Teufelswald und finden sich in den Hügeln von Razorfen. Es ist ein düsterer Name, den man zwischen so vielen zerstörten Feldern lernt." }, { "Das Elixier der Untotenentdeckung und Arthas' Gabe sind ihre beiden bekannten Zubereitungen. Keine von beiden hellt auf, was an einem Bündel aus diesem Land haftet." } },
    [8838] = { { "Sonnengras bleibt ein willkommener Fund in so unruhigem Land wie dem Teufelswald und den Pestländern, ebenso wie in grüneren Ländern weiter südlich." }, { "Überragende Heil- und Manatränke verwenden es beide." } },
    [8839] = { { "Blindkraut führt einen Sammler durch die Sümpfe des Elends und Un'Goro, mit einem weiteren Vorrat unter der Erde in Maraudon." }, { "Überragende Manatränke und das Arkane Elixier verlangen danach. In Arthas' Gabe begleitet es Arthas' Tränen." } },
    [8845] = { { "Geisterpilze machen Höhlenland eine sorgfältige Suche wert. Das Hinterland und Desolace haben sie, und weitere finden sich in Maraudon und Düsterbruch." }, { "Alchemisten verwenden sie für Unsichtbarkeit und Schattenmacht, stellen aber auch Geisterfarbstoff für Schneider her. Ein Pilz, der aus der Dunkelheit geholt wurde, kann seine Reise als Farbe eines Gewands beenden." } },
    [8846] = { { "Gromsblut findet sich auf dem verseuchten Boden des Teufelswalds, nahe dem Dunklen Portal und in Düsterbruch. Die Sammelroute führt an einigen der beständigsten Spuren vorbei, die die Legion in der Welt hinterlassen hat." }, { "Das Fläschchen der Titanen und das Elixier der rohen Gewalt verlangen beide danach. Ebenso das Elixier des Dämonentötens, eine besonders befriedigende Verwendung für etwas, das in solcher Gesellschaft gesammelt wurde." } },
  },
